// Step 92: every video keeps its own shape (16:9 stays wide, 9:16 stays upright).
// Run from the project folder:  node step-92-video-shape.mjs
import { mkdirSync, writeFileSync, existsSync } from "node:fs";
import { dirname } from "node:path";

if (!existsSync("src/components/social/Reels.tsx")) {
  console.error("Run this from the Men-s-Social-True project folder.");
  process.exit(1);
}

const files = {"src/lib/media/videoShape.ts":"\"use client\";\n\n// Step 92: every video keeps its own shape.\n// A wide video (16:9) shows wide, an upright one (9:16) shows upright, and anything in between\n// (4:5, square) shows as it was filmed. The app reads the shape from the video itself the first\n// time it loads, and remembers it on this phone so the box is the right size straight away next time.\n// YouTube tells us nothing before it plays, so Shorts are upright and other YouTube links are wide.\n\nimport { useCallback, useEffect, useState } from \"react\";\nimport { isYouTube, isYouTubeShort } from \"../content/youtube\";\n\nexport const UPRIGHT = 9 / 16;\nexport const WIDE = 16 / 9;\n\nconst KEY = \"ms_video_shape\";\nconst MAX_KEPT = 300;\nconst known = new Map<string, number>();\nconst listeners = new Set<() => void>();\nlet loaded = false;\n\nconst valid = (r: unknown): r is number => typeof r === \"number\" && Number.isFinite(r) && r > 0.2 && r < 5;\n\n/** The same file with or without \"#t=0.5\" is the same video. */\nexport const shapeKey = (url: string) => url.split(\"#\")[0];\n\n/** Width ÷ height, or null when the video hasn't said yet. */\nexport function ratioFrom(width: number, height: number): number | null {\n  if (!(width > 0 && height > 0)) return null;\n  const r = width / height;\n  return valid(r) ? Math.round(r * 1000) / 1000 : null;\n}\n\n/** The shape before the video has loaded: what we remember, YouTube's kind, or the fallback. */\nexport function shapeOf(url: string | null | undefined, fallback: number): number {\n  if (!url) return fallback;\n  if (isYouTube(url)) return isYouTubeShort(url) ? UPRIGHT : WIDE;\n  return known.get(shapeKey(url)) ?? fallback;\n}\n\nfunction load() {\n  if (loaded || typeof window === \"undefined\") return;\n  loaded = true;\n  try {\n    const raw = localStorage.getItem(KEY);\n    if (raw) for (const [k, v] of Object.entries(JSON.parse(raw) as Record<string, unknown>)) if (valid(v)) known.set(k, v);\n  } catch {}\n}\n\nfunction persist() {\n  try {\n    const entries = [...known].slice(-MAX_KEPT);\n    localStorage.setItem(KEY, JSON.stringify(Object.fromEntries(entries)));\n  } catch {}\n}\n\n/** Remember a video's real shape (from its width and height). */\nexport function rememberShape(url: string | null | undefined, width: number, height: number) {\n  if (!url || isYouTube(url)) return;\n  const r = ratioFrom(width, height);\n  if (r === null) return;\n  load();\n  const k = shapeKey(url);\n  if (known.get(k) === r) return;\n  known.delete(k); // newest last, so the oldest drop off first\n  known.set(k, r);\n  persist();\n  listeners.forEach((l) => l());\n}\n\n/**\n * The shape of one video.\n *   const shape = useVideoShape(url, UPRIGHT);\n *   <div style={{ aspectRatio: shape.ratio }}>  <video onLoadedMetadata={shape.measure} … />\n * `fallback` is used until the video has loaded once (reels: UPRIGHT, other videos: WIDE).\n */\nexport function useVideoShape(url: string | null | undefined, fallback: number = WIDE) {\n  const [, bump] = useState(0);\n  useEffect(() => {\n    load();\n    const l = () => bump((n) => n + 1);\n    listeners.add(l);\n    l(); // pick up what this phone already remembers (after the first paint, so server and phone agree)\n    return () => {\n      listeners.delete(l);\n    };\n  }, []);\n\n  const ratio = shapeOf(url, fallback);\n  const measure = useCallback(\n    (e: React.SyntheticEvent<HTMLVideoElement>) => {\n      const v = e.currentTarget;\n      rememberShape(url, v.videoWidth, v.videoHeight);\n    },\n    [url],\n  );\n\n  return { ratio, upright: ratio < 1, wide: ratio > 1, measure };\n}\n","src/lib/media/videoShape.test.ts":"import { describe, expect, it } from \"vitest\";\nimport { UPRIGHT, WIDE, ratioFrom, rememberShape, shapeKey, shapeOf } from \"./videoShape\";\n\ndescribe(\"video shape (Step 92)\", () => {\n  it(\"reads wide and upright videos the right way round\", () => {\n    expect(ratioFrom(1920, 1080)).toBeCloseTo(16 / 9, 2);\n    expect(ratioFrom(1080, 1920)).toBeCloseTo(9 / 16, 2);\n    expect(ratioFrom(0, 0)).toBeNull();\n  });\n\n  it(\"uses the fallback until the video has loaded, then its real shape\", () => {\n    const url = \"https://x.supabase.co/storage/v1/object/public/media/wide.mp4\";\n    expect(shapeOf(url, UPRIGHT)).toBe(UPRIGHT);\n    rememberShape(url, 1280, 720);\n    expect(shapeOf(url, UPRIGHT)).toBeCloseTo(16 / 9, 2);\n    expect(shapeOf(`${url}#t=0.5`, UPRIGHT)).toBeCloseTo(16 / 9, 2);\n    expect(shapeKey(`${url}#t=0.5`)).toBe(url);\n  });\n\n  it(\"knows YouTube Shorts are upright and other YouTube videos wide\", () => {\n    expect(shapeOf(\"https://www.youtube.com/shorts/abcdefghijk\", WIDE)).toBe(UPRIGHT);\n    expect(shapeOf(\"https://www.youtube.com/watch?v=abcdefghijk\", UPRIGHT)).toBe(WIDE);\n  });\n});\n","src/components/media/ShapedVideo.tsx":"\"use client\";\n\n// Step 92: a video player that takes the video's own shape.\n// 16:9 shows wide and full width. 9:16 shows upright, centred, never taller than `maxHeight`.\n// Nothing is cut off and nothing is stretched: the box is made the video's shape, so there are no black bars\n// once the video has loaded once (the shape is remembered on the phone, see lib/media/videoShape.ts).\n\nimport { forwardRef } from \"react\";\nimport { WIDE, useVideoShape } from \"@/lib/media/videoShape\";\n\ntype Props = React.VideoHTMLAttributes<HTMLVideoElement> & {\n  src: string | undefined;\n  /** The shape to use until the video has loaded once. */\n  fallback?: number;\n  /** The tallest it may be, as CSS (default: most of the screen). */\n  maxHeight?: string;\n};\n\nconst ShapedVideo = forwardRef<HTMLVideoElement, Props>(function ShapedVideo(\n  { src, fallback = WIDE, maxHeight = \"78dvh\", className = \"\", style, onLoadedMetadata, ...rest },\n  ref,\n) {\n  const shape = useVideoShape(src, fallback);\n  return (\n    <video\n      ref={ref}\n      src={src}\n      {...rest}\n      onLoadedMetadata={(e) => {\n        shape.measure(e);\n        onLoadedMetadata?.(e);\n      }}\n      style={{\n        aspectRatio: shape.ratio,\n        // As wide as it can be without getting taller than maxHeight\n        width: `min(100%, calc(${maxHeight} * ${shape.ratio}))`,\n        ...style,\n      }}\n      className={`mx-auto block h-auto bg-black object-contain ${className}`}\n    />\n  );\n});\n\nexport default ShapedVideo;\n","src/components/social/Reels.tsx":"\"use client\";\n\n// Reels on Discover, like Instagram Reels:\n//  - ReelPost (Step 73): a full-width, tall reel inside the feed. It plays silently while it's the reel\n//    most on screen (only one at a time, see lib/content/feedPlayer.ts) and pauses when he scrolls past.\n//    Nothing is printed over the video, so the video's own text stays readable: the name, title, caption\n//    and buttons sit under it. Tapping the video opens the full-screen viewer with sound on.\n//  - ReelsViewer: full screen, swipe up for the next one. Like, save, share, \"I did it\".\n//    Step 77: it grows out of the reel he tapped, and pulling down on the first reel shrinks it back\n//    into its card in the feed (✕ and the phone's Back button do the same). Springs keep his finger's speed.\n// Only the reel on screen (and the next one) loads, to save his data. Late at night, or after 15 reels,\n// a \"that's enough for tonight\" card comes up (see lib/content/reels.ts).\n\nimport { sized } from \"@/lib/media/image\";\nimport Photo from \"@/components/media/Photo\";\nimport ReelCaption from \"./ReelCaption\";\nimport { cleanTitle } from \"@/lib/content/caption\";\nimport { Fragment, useCallback, useEffect, useId, useLayoutEffect, useMemo, useRef, useState } from \"react\";\nimport { createPortal } from \"react-dom\";\nimport Link from \"next/link\";\nimport { ArrowRight, Bookmark, Check, Heart, Moon, Play, Send, Volume2, VolumeX, X } from \"lucide-react\";\nimport { contentHref } from \"./ContentCards\";\nimport { useToast } from \"@/components/motion/Toast\";\nimport BrandMark from \"@/components/brand/BrandMark\";\nimport { trackContent } from \"@/lib/analytics/track\";\nimport { reelCaption, softEndIndex } from \"@/lib/content/reels\";\nimport { feedPlayer, useFeedSound, usePlayingReel } from \"@/lib/content/feedPlayer\";\nimport { youtubeId, youtubeThumb } from \"@/lib/content/youtube\";\nimport { YouTubeFrame } from \"@/components/media/YouTubeFrame\";\nimport type { ContentItem } from \"@/lib/content/types\";\nimport { socialStore, useSocial } from \"@/lib/social/store\";\nimport { triedStore, useTried } from \"@/lib/social/tried\";\nimport { useT } from \"@/lib/i18n\";\nimport { habitsStore } from \"@/lib/social/discoverPrefs\";\nimport { animateSpring, releaseVelocity, type SpringHandle } from \"@/lib/motion/spring\";\nimport { haptic } from \"@/lib/motion/haptics\";\nimport { useSaveData } from \"@/lib/media/saveData\";\nimport { ShareSheet } from \"./Hooks\";\nimport { UPRIGHT, useVideoShape } from \"@/lib/media/videoShape\";\n\nconst SOUND_KEY = \"ms_reels_sound\";\n\n/** The reel's picture: its cover photo, or the video's first frame. */\nfunction Poster({ reel, onMeasure }: { reel: ContentItem; onMeasure?: React.ReactEventHandler<HTMLVideoElement> }) {\n  const yt = youtubeId(reel.videoUrl);\n  if (reel.coverImageUrl || yt)\n    return <Photo src={reel.coverImageUrl || youtubeThumb(yt!)} className=\"absolute inset-0 h-full w-full object-cover\" />;\n  return (\n    <video src={`${reel.videoUrl}#t=0.5`} muted playsInline preload=\"metadata\" onLoadedMetadata={onMeasure} className=\"absolute inset-0 h-full w-full object-cover\" aria-hidden />\n  );\n}\n\n/* ───────── A reel in the feed ───────── */\nexport function ReelPost({ reel, onOpen }: { reel: ContentItem; onOpen: () => void }) {\n  const t = useT();\n  const sw = t.lang === \"sw\";\n  const showToast = useToast();\n  const tried = useTried();\n  const social = useSocial();\n  const key = `${reel.id}:${useId()}`;\n  const box = useRef<HTMLDivElement>(null);\n  const video = useRef<HTMLVideoElement>(null);\n  const [near, setNear] = useState(false); // any part on screen → load the video\n  const shape = useVideoShape(reel.videoUrl, UPRIGHT); // Step 92: wide videos stay wide, upright stay upright\n  const [progress, setProgress] = useState(0);\n  const playing = usePlayingReel() === key;\n  const sound = useFeedSound();\n  const liked = Boolean(tried.liked[reel.id]);\n  const saved = Boolean(social.bookmarks[reel.id]);\n  const title = cleanTitle(sw && reel.titleSw ? reel.titleSw : reel.title); // Step 81: no brand, no shouting\n  const caption = reelCaption(reel, sw);\n  const handle = \"@kayaniherbs\"; // one name everywhere (Step 84)\n  // Step 90: Save data (his choice in Me, or Data Saver / a slow connection): reels in the feed wait for a tap\n  const lite = useSaveData();\n  const yt = youtubeId(reel.videoUrl);\n\n  // Tell the feed player how much of this reel is on screen\n  useEffect(() => {\n    const el = box.current;\n    if (!el || typeof IntersectionObserver === \"undefined\") return;\n    const io = new IntersectionObserver(\n      ([e]) => {\n        setNear(e.isIntersecting);\n        if (!lite) feedPlayer.report(key, e.isIntersecting ? e.intersectionRatio : 0);\n      },\n      { threshold: [0, 0.25, 0.5, 0.6, 0.7, 0.8, 0.9, 1] },\n    );\n    io.observe(el);\n    return () => {\n      io.disconnect();\n      feedPlayer.leave(key);\n    };\n  }, [key, lite]);\n\n  // Play only while this is the chosen reel; pause the moment it isn't\n  useEffect(() => {\n    const v = video.current;\n    if (!v) return;\n    if (playing) {\n      v.muted = !sound;\n      void v.play().catch(() => {\n        // Sound without a tap can be blocked: fall back to silent\n        if (!v.muted) {\n          v.muted = true;\n          feedPlayer.setSound(false);\n          void v.play().catch(() => {});\n        }\n      });\n    } else v.pause();\n  }, [playing, near, sound]);\n\n  const [sharing, setSharing] = useState(false);\n\n  return (\n    <article className=\"overflow-hidden rounded-[20px] bg-surface ring-1 ring-line\">\n      <ShareSheet open={sharing} onClose={() => setSharing(false)} item={reel} spec={reel.action} t={t} />\n      <header className=\"flex items-center gap-2.5 px-3 py-2.5\">\n        <BrandMark size={32} className=\"shrink-0\" />\n        <div className=\"min-w-0 flex-1\">\n          <p className=\"truncate text-[0.8125rem] font-bold leading-tight\">{handle}</p>\n          <p className=\"truncate text-[0.6875rem] text-ink-soft\">{t(\"Reel\")}</p>\n        </div>\n      </header>\n\n      {/* The video, nothing written over it, in its own shape (Step 92). Never taller than the screen. */}\n      <div\n        ref={box}\n        data-reel-card={reel.id}\n        style={{ aspectRatio: shape.ratio }}\n        className=\"relative max-h-[min(78svh,820px)] w-full overflow-hidden bg-black transition-[aspect-ratio] duration-300\"\n      >\n        {yt && near && !lite && (\n          <YouTubeFrame id={yt} playing={playing} muted={!sound} loop title={title} className=\"absolute inset-0\" onProgress={(c, d) => setProgress(c / d)} />\n        )}\n        <button type=\"button\" onClick={onOpen} className=\"absolute inset-0 block h-full w-full\" aria-label={`${t(\"Watch\")}: ${title}`}>\n          {yt && near && !lite ? null : near && !lite ? (\n            <video\n              ref={video}\n              src={reel.videoUrl}\n              poster={reel.coverImageUrl ? sized(reel.coverImageUrl, 720) : undefined}\n              muted\n              loop\n              playsInline\n              preload=\"metadata\"\n              onLoadedMetadata={shape.measure}\n              onTimeUpdate={(e) => {\n                const v = e.currentTarget;\n                setProgress(v.duration ? v.currentTime / v.duration : 0);\n              }}\n              className={`absolute inset-0 h-full w-full ${shape.upright ? \"object-cover\" : \"object-contain\"}`}\n            />\n          ) : (\n            <Poster reel={reel} onMeasure={shape.measure} />\n          )}\n          {lite && (\n            <span className=\"absolute left-1/2 top-1/2 flex h-14 w-14 -translate-x-1/2 -translate-y-1/2 items-center justify-center rounded-full bg-black/45 text-white backdrop-blur\">\n              <Play size={24} fill=\"currentColor\" />\n            </span>\n          )}\n        </button>\n        {!lite && (\n          <button\n            type=\"button\"\n            onClick={() => feedPlayer.setSound(!sound)}\n            aria-label={t(sound ? \"Sound off\" : \"Sound on\")}\n            className=\"absolute bottom-3 right-3 flex h-8 w-8 items-center justify-center rounded-full bg-black/55 text-white backdrop-blur active:scale-90\"\n          >\n            {sound ? <Volume2 size={15} /> : <VolumeX size={15} />}\n          </button>\n        )}\n        <div className=\"pointer-events-none absolute inset-x-0 bottom-0 h-[3px] bg-white/15\">\n          <div className=\"h-full bg-white/90\" style={{ width: `${progress * 100}%` }} />\n        </div>\n      </div>\n\n      {/* Buttons under the video, like Instagram */}\n      <div className=\"flex items-center gap-1 px-1.5 pt-1.5\">\n        <IconButton label={t(liked ? \"Helped ✓\" : \"This helped\")} onClick={() => triedStore.toggleLike(reel.id)}>\n          <Heart size={24} className={liked ? \"text-red-500\" : \"\"} fill={liked ? \"currentColor\" : \"none\"} />\n        </IconButton>\n        <IconButton label={t(\"Share\")} onClick={() => setSharing(true)}>\n          <Send size={22} />\n        </IconButton>\n        <span className=\"flex-1\" />\n        <IconButton\n          label={t(saved ? \"Saved\" : \"Save\")}\n          onClick={() => {\n            const now = socialStore.toggleBookmark(reel.id);\n            if (now) trackContent(reel.id, \"save\");\n            showToast(t(now ? \"Saved to your playbook\" : \"Removed from your playbook\"));\n          }}\n        >\n          <Bookmark size={23} fill={saved ? \"currentColor\" : \"none\"} />\n        </IconButton>\n      </div>\n\n      <div className=\"px-3.5 pb-3.5\">\n        <p className=\"mt-0.5 text-[0.875rem] leading-snug\">\n          <span className=\"font-bold\">{handle}</span> <span className=\"font-semibold\">{title}</span>\n        </p>\n        {/* Two lines, then \"more\" opens it as a tidy list (Step 81) */}\n        <ReelCaption text={caption} className=\"mt-0.5 text-[0.8125rem] leading-snug\" />\n      </div>\n    </article>\n  );\n}\n\nfunction IconButton({ label, onClick, children }: { label: string; onClick: () => void; children: React.ReactNode }) {\n  return (\n    <button type=\"button\" onClick={onClick} aria-label={label} title={label} className=\"flex h-10 w-10 items-center justify-center rounded-full text-ink transition-transform active:scale-90\">\n      {children}\n    </button>\n  );\n}\n\n/* ───────── Full screen ───────── */\n/** Where the viewer's picture sits: moved, shrunk, cut to the card's height, rounded, and how dark the page behind is. */\ntype Pose = { tx: number; ty: number; s: number; inset: number; radius: number; dim: number };\nconst FULL: Pose = { tx: 0, ty: 0, s: 1, inset: 0, radius: 0, dim: 1 };\nconst mix = (a: Pose, b: Pose, p: number): Pose => ({\n  tx: a.tx + (b.tx - a.tx) * p,\n  ty: a.ty + (b.ty - a.ty) * p,\n  s: a.s + (b.s - a.s) * p,\n  inset: a.inset + (b.inset - a.inset) * p,\n  radius: a.radius + (b.radius - a.radius) * p,\n  dim: a.dim + (b.dim - a.dim) * p,\n});\n\n/** The pose that makes the full-screen viewer sit exactly on a reel's card in the feed. */\nfunction cardPose(rect: DOMRect): Pose {\n  const W = window.innerWidth;\n  const H = window.innerHeight;\n  const s = rect.width / W;\n  return {\n    tx: rect.left + rect.width / 2 - W / 2,\n    ty: rect.top + rect.height / 2 - H / 2,\n    s,\n    inset: Math.max(0, (H - rect.height / s) / 2),\n    radius: 20 / s,\n    dim: 0,\n  };\n}\n\n/** The reel's card in the feed, if it's on screen now (otherwise the viewer just slides down and away). */\nfunction cardRect(id: string | undefined): DOMRect | null {\n  if (!id) return null;\n  const el = document.querySelector<HTMLElement>(`[data-reel-card=\"${CSS.escape(id)}\"]`);\n  const r = el?.getBoundingClientRect();\n  if (!r || r.width < 40 || r.bottom < 0 || r.top > window.innerHeight) return null;\n  return r;\n}\n\nexport function ReelsViewer({ reels, start, onClose, withSound = false }: { reels: ContentItem[]; start: number; onClose: () => void; withSound?: boolean }) {\n  const t = useT();\n  const strip = useRef<HTMLDivElement>(null);\n  const root = useRef<HTMLDivElement>(null);\n  const frame = useRef<HTMLDivElement>(null);\n  const [active, setActive] = useState(start);\n  // Opened by tapping a reel → sound on (the tap allows it). Otherwise his last choice.\n  const [sound, setSound] = useState(() => {\n    if (withSound) return true;\n    try {\n      return sessionStorage.getItem(SOUND_KEY) === \"1\";\n    } catch {\n      return false;\n    }\n  });\n  // The feed's reels stop while the viewer is open\n  useEffect(() => {\n    feedPlayer.setViewerOpen(true);\n    return () => feedPlayer.setViewerOpen(false);\n  }, []);\n  const [endDismissed, setEndDismissed] = useState(false);\n  const endAt = useMemo(() => (endDismissed ? -1 : softEndIndex(start, reels.length, new Date())), [endDismissed, start, reels.length]);\n\n  // ---- The viewer's picture: growing out of the card, following his finger, shrinking back (Step 77) ----\n  const pose = useRef<Pose>(FULL);\n  const anim = useRef<SpringHandle | null>(null);\n  const leaving = useRef(false);\n  const place = useCallback((p: Pose) => {\n    pose.current = p;\n    const f = frame.current;\n    const r = root.current;\n    if (!f || !r) return;\n    f.style.transform = p === FULL || (p.tx === 0 && p.ty === 0 && p.s === 1) ? \"\" : `translate3d(${p.tx}px, ${p.ty}px, 0) scale(${p.s})`;\n    f.style.clipPath = p.inset > 0.5 || p.radius > 0.5 ? `inset(${p.inset}px 0 round ${p.radius}px)` : \"\";\n    r.style.backgroundColor = `rgb(0 0 0 / ${Math.max(0, Math.min(1, p.dim))})`;\n  }, []);\n  /** Spring from where the picture is now to `to`; `speed` is in \"whole moves per second\". */\n  const glide = useCallback(\n    (to: Pose, speed = 0, done?: () => void, response = 0.36) => {\n      anim.current?.stop();\n      const from = pose.current;\n      anim.current = animateSpring(0, 1, (p) => place(mix(from, to, p)), {\n        damping: 1,\n        response,\n        velocity: speed,\n        onDone: () => {\n          anim.current = null;\n          place(to);\n          done?.();\n        },\n      });\n    },\n    [place],\n  );\n  // Opening: it grows out of the reel he tapped\n  useLayoutEffect(() => {\n    const rect = cardRect(reels[start]?.id);\n    if (!rect) return;\n    place(cardPose(rect));\n    glide(FULL, 0, undefined, 0.4);\n    return () => anim.current?.stop();\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, []);\n  /** Shrink back into the card of the reel on screen (or slide down if that card isn't in view), then close. */\n  const shrinkAway = useCallback(\n    (then: () => void, speedPx = 0) => {\n      if (leaving.current) return;\n      leaving.current = true;\n      const rect = cardRect(reels[activeRef.current]?.id);\n      const H = window.innerHeight;\n      const to: Pose = rect ? cardPose(rect) : { ...pose.current, ty: H, dim: 0 };\n      const gap = Math.max(60, Math.abs(to.ty - pose.current.ty));\n      glide(to, Math.max(0, Math.min(8, speedPx / gap)), then, 0.34);\n    },\n    [glide, reels],\n  );\n  const activeRef = useRef(active);\n  activeRef.current = active;\n\n  // The phone's Back button closes the reels instead of leaving the app\n  const closing = useRef(false);\n  useEffect(() => {\n    history.pushState({ reels: true }, \"\");\n    const onPop = () => {\n      closing.current = true;\n      if (leaving.current) return onClose(); // already shrinking: Back came from our own close\n      shrinkAway(onClose);\n    };\n    window.addEventListener(\"popstate\", onPop);\n    const onKey = (e: KeyboardEvent) => e.key === \"Escape\" && closeRef.current();\n    document.addEventListener(\"keydown\", onKey);\n    document.documentElement.style.overflow = \"hidden\";\n    return () => {\n      window.removeEventListener(\"popstate\", onPop);\n      document.removeEventListener(\"keydown\", onKey);\n      document.documentElement.style.overflow = \"\";\n    };\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, []);\n  /** ✕, Escape, \"Close reels\": shrink back into the card, then leave. */\n  const close = useCallback(\n    (speedPx = 0) => {\n      shrinkAway(() => {\n        if (!closing.current) history.back();\n        else onClose();\n      }, speedPx);\n    },\n    [onClose, shrinkAway],\n  );\n\n  const closeRef = useRef(() => close());\n  closeRef.current = () => close();\n\n  // ---- Pulling down on the first reel closes the viewer ----\n  // Touch events (not pointer events), because the browser owns vertical swipes on the reel strip;\n  // at the very top a downward pull is ours, so we stop the browser there.\n  useEffect(() => {\n    const el = root.current;\n    const st = strip.current;\n    if (!el || !st) return;\n    let g: { y: number; x: number; on: boolean; done: boolean; samples: { t: number; x: number }[] } | null = null;\n    const onStart = (e: TouchEvent) => {\n      if (e.touches.length !== 1 || leaving.current) return (g = null);\n      anim.current?.stop();\n      const p = e.touches[0];\n      // Caught while springing back: carry on from where the picture is, not from the top\n      const caught = pose.current.ty > 0;\n      g = { y: p.clientY - (caught ? pose.current.ty : 0), x: p.clientX - (caught ? pose.current.tx * 2 : 0), on: caught, done: false, samples: [{ t: performance.now(), x: p.clientY }] };\n    };\n    const onMove = (e: TouchEvent) => {\n      if (!g || g.done) return;\n      const p = e.touches[0];\n      const dy = p.clientY - g.y;\n      const dx = p.clientX - g.x;\n      if (!g.on) {\n        if (Math.abs(dy) < 8 && Math.abs(dx) < 8) return;\n        // Only a mostly-downward pull while the first reel is fully on screen\n        if (dy > 0 && dy > Math.abs(dx) * 1.2 && st.scrollTop <= 1) g.on = true;\n        else return void (g.done = true);\n      }\n      if (e.cancelable) e.preventDefault();\n      const H = window.innerHeight;\n      const down = Math.max(0, dy);\n      // The picture follows the finger 1:1 and shrinks a little as it goes, the feed shows through behind\n      place({ tx: dx * 0.5, ty: down, s: 1 - Math.min(down / H, 1) * 0.35, inset: 0, radius: Math.min(down / 4, 28), dim: 1 - Math.min(down / (H * 0.6), 1) * 0.85 });\n      const now = performance.now();\n      g.samples.push({ t: now, x: p.clientY });\n      while (g.samples.length > 2 && now - g.samples[0].t > 100) g.samples.shift();\n    };\n    const onEnd = () => {\n      if (!g?.on) return (g = null);\n      const v = releaseVelocity(g.samples); // px/s, positive = downward\n      const down = pose.current.ty;\n      g = null;\n      if (v > 450 || (down > window.innerHeight * 0.18 && v > -200)) {\n        haptic(\"tick\");\n        close(Math.max(v, 0));\n      } else {\n        // Not far or fast enough: back up to full screen at his finger's speed\n        const gap = Math.max(60, down);\n        glide(FULL, Math.max(0, Math.min(8, -v / gap)), undefined, 0.32);\n      }\n    };\n    el.addEventListener(\"touchstart\", onStart, { passive: true });\n    el.addEventListener(\"touchmove\", onMove, { passive: false });\n    el.addEventListener(\"touchend\", onEnd);\n    el.addEventListener(\"touchcancel\", onEnd);\n    return () => {\n      el.removeEventListener(\"touchstart\", onStart);\n      el.removeEventListener(\"touchmove\", onMove);\n      el.removeEventListener(\"touchend\", onEnd);\n      el.removeEventListener(\"touchcancel\", onEnd);\n    };\n  }, [close, glide, place]);\n\n  // Start at the reel he tapped\n  useEffect(() => {\n    const el = strip.current?.querySelector<HTMLElement>(`[data-slide=\"r${start}\"]`);\n    el?.scrollIntoView({ block: \"start\" });\n  }, [start]);\n\n  // Which slide is on screen\n  useEffect(() => {\n    const root = strip.current;\n    if (!root || typeof IntersectionObserver === \"undefined\") return;\n    const io = new IntersectionObserver(\n      (entries) => {\n        for (const e of entries) {\n          if (!e.isIntersecting || e.intersectionRatio < 0.6) continue;\n          const key = (e.target as HTMLElement).dataset.slide ?? \"\";\n          if (key.startsWith(\"r\")) setActive(Number(key.slice(1)));\n        }\n      },\n      { root, threshold: [0.6] },\n    );\n    root.querySelectorAll(\"[data-slide]\").forEach((s) => io.observe(s));\n    return () => io.disconnect();\n  }, [reels.length, endAt]);\n\n  const toggleSound = () => {\n    setSound((s) => {\n      try {\n        sessionStorage.setItem(SOUND_KEY, s ? \"0\" : \"1\");\n      } catch {}\n      return !s;\n    });\n  };\n\n  if (typeof document === \"undefined\") return null;\n  return createPortal(\n    <div ref={root} className=\"fixed inset-0 z-[60] bg-black text-white\" role=\"dialog\" aria-modal=\"true\" aria-label={t(\"Reels\")}>\n      <div ref={frame} className=\"absolute inset-0 origin-center overflow-hidden will-change-transform\">\n      <div ref={strip} className=\"no-scrollbar h-full snap-y snap-mandatory overflow-y-scroll overscroll-contain\">\n        {reels.map((r, i) => (\n          <Fragment key={r.id}>\n            {i === endAt && (\n              <section data-slide=\"end\" className=\"relative flex h-[100dvh] snap-start flex-col items-center justify-center gap-4 px-8 text-center\">\n                <Moon size={40} className=\"text-mint\" />\n                <p className=\"font-display text-2xl font-bold\">{t(\"That's enough for tonight\")}</p>\n                <p className=\"max-w-xs text-sm text-white/75\">{t(\"Put the phone down and rest. Your next reels will be here tomorrow.\")}</p>\n                <button onClick={() => close()} className=\"mt-2 rounded-full bg-white px-6 py-3 text-sm font-bold text-forest-deep\">\n                  {t(\"Close reels\")}\n                </button>\n                <button\n                  onClick={() => {\n                    setEndDismissed(true);\n                    requestAnimationFrame(() => strip.current?.querySelector<HTMLElement>(`[data-slide=\"r${i}\"]`)?.scrollIntoView({ behavior: \"smooth\" }));\n                  }}\n                  className=\"text-xs font-semibold text-white/60 underline underline-offset-4\"\n                >\n                  {t(\"Keep watching\")}\n                </button>\n              </section>\n            )}\n            <ReelSlide\n              reel={r}\n              index={i}\n              active={i === active}\n              near={Math.abs(i - active) <= 1}\n              sound={sound}\n              onToggleSound={toggleSound}\n              onSoundBlocked={() => setSound(false)}\n              onLeave={() => {\n                closing.current = true;\n                onClose();\n              }}\n              onFinished={() => {\n                // Step 86: on to the next reel (or the \"enough for tonight\" / \"watched them all\" card)\n                const here = strip.current?.querySelector<HTMLElement>(`[data-slide=\"r${i}\"]`);\n                const next = here?.nextElementSibling as HTMLElement | null;\n                if (next) strip.current?.scrollTo({ top: next.offsetTop, behavior: \"smooth\" });\n              }}\n            />\n          </Fragment>\n        ))}\n        <section data-slide=\"done\" className=\"flex h-[100dvh] snap-start flex-col items-center justify-center gap-3 px-8 text-center\">\n          <Check size={36} className=\"text-mint\" />\n          <p className=\"font-display text-xl font-bold\">{t(\"You've watched them all\")}</p>\n          <p className=\"text-sm text-white/70\">{t(\"New reels come every week.\")}</p>\n          <button onClick={() => close()} className=\"mt-2 rounded-full bg-white px-6 py-3 text-sm font-bold text-forest-deep\">\n            {t(\"Back to Discover\")}\n          </button>\n        </section>\n      </div>\n\n      <div className=\"pointer-events-none absolute inset-x-0 top-0 flex items-center justify-between p-3 pt-[max(0.75rem,env(safe-area-inset-top))]\">\n        <button onClick={() => close()} aria-label={t(\"Close\")} className=\"pointer-events-auto flex h-10 w-10 items-center justify-center rounded-full bg-black/40 backdrop-blur\">\n          <X size={20} />\n        </button>\n        <p className=\"font-display text-lg font-bold drop-shadow\">{t(\"Reels\")}</p>\n        <button onClick={toggleSound} aria-label={t(sound ? \"Sound off\" : \"Sound on\")} className=\"pointer-events-auto flex h-10 w-10 items-center justify-center rounded-full bg-black/40 backdrop-blur\">\n          {sound ? <Volume2 size={19} /> : <VolumeX size={19} />}\n        </button>\n      </div>\n      </div>\n    </div>,\n    document.body,\n  );\n}\n\nfunction ReelSlide({\n  reel,\n  index,\n  active,\n  near,\n  sound,\n  onToggleSound,\n  onSoundBlocked,\n  onLeave,\n  onFinished,\n}: {\n  reel: ContentItem;\n  index: number;\n  active: boolean;\n  near: boolean;\n  sound: boolean;\n  onToggleSound: () => void;\n  onSoundBlocked: () => void;\n  onLeave: () => void;\n  /** It played through once: go to the next reel (Step 86). */\n  onFinished: () => void;\n}) {\n  const t = useT();\n  const sw = t.lang === \"sw\";\n  const showToast = useToast();\n  const tried = useTried();\n  const social = useSocial();\n  const video = useRef<HTMLVideoElement>(null);\n  const [progress, setProgress] = useState(0);\n  const liked = Boolean(tried.liked[reel.id]);\n  const done = Boolean(tried.done[reel.id]);\n  const saved = Boolean(social.bookmarks[reel.id]);\n  const title = cleanTitle(sw && reel.titleSw ? reel.titleSw : reel.title); // Step 81: no brand, no shouting\n  const caption = reelCaption(reel, sw);\n\n  // How much of it he watched (for the reels/reading mix, Step 71): counted when he moves on\n  const watched = useRef({ seconds: 0, max: 0, on: false });\n  const yt = youtubeId(reel.videoUrl);\n  // Step 92: phone-shaped videos fill the screen; wide or square ones show whole (black above and below)\n  const shape = useVideoShape(reel.videoUrl, UPRIGHT);\n  const fill = shape.ratio < 0.7;\n  useEffect(() => {\n    const v = video.current;\n    if (!v && !(yt && active)) {\n      if (!active && watched.current.on) {\n        habitsStore.reelWatched(watched.current.seconds, watched.current.max);\n        watched.current.on = false;\n      }\n      return;\n    }\n    if (active) {\n      if (v) v.currentTime = 0;\n      if (v) void v.play().catch(() => {\n        // Some phones block sound until he taps: play silently instead, and the sound button shows off\n        if (!v.muted) {\n          v.muted = true;\n          onSoundBlocked();\n          void v.play().catch(() => {});\n        }\n      });\n      socialStore.recordOpen(reel.id);\n      trackContent(reel.id, \"view\");\n      watched.current = { seconds: 0, max: 0, on: true };\n    } else {\n      v?.pause();\n      if (watched.current.on) {\n        habitsStore.reelWatched(watched.current.seconds, watched.current.max);\n        watched.current.on = false;\n      }\n    }\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [active, reel.id]);\n  // Closing the reels counts the one on screen too\n  useEffect(\n    () => () => {\n      if (watched.current.on) habitsStore.reelWatched(watched.current.seconds, watched.current.max);\n    },\n    [],\n  );\n  useEffect(() => {\n    if (video.current) video.current.muted = !sound;\n  }, [sound]);\n\n  const [sharing, setSharing] = useState(false);\n  // Step 86: once it has played through, the next reel comes on its own (once per time it's on screen)\n  const ended = useRef(false);\n  const last = useRef(0);\n  useEffect(() => {\n    ended.current = false;\n    last.current = 0;\n  }, [active]);\n  const playedThrough = () => {\n    if (!active || ended.current) return;\n    ended.current = true;\n    onFinished();\n  };\n\n  return (\n    <section data-slide={`r${index}`} className=\"relative h-[100dvh] snap-start overflow-hidden bg-black\">\n      {near && yt ? (\n        <>\n          <YouTubeFrame\n            id={yt}\n            playing={active}\n            muted={!sound}\n            loop\n            title={title}\n            className=\"absolute inset-0\"\n            onProgress={(c, d) => {\n              const f = c / d;\n              setProgress(f);\n              if (!active) return;\n              const w = watched.current;\n              // It loops: jumping back to the start after the end counts as finished\n              if (w.seconds > d - 1.5 && c < 1) {\n                if (w.max < 1) trackContent(reel.id, \"complete\");\n                w.max = 1;\n                playedThrough();\n              }\n              w.seconds = Math.max(w.seconds, c);\n              w.max = Math.max(w.max, f);\n            }}\n          />\n          <button type=\"button\" onClick={onToggleSound} aria-label={t(sound ? \"Sound off\" : \"Sound on\")} className=\"absolute inset-0\" />\n        </>\n      ) : near ? (\n        <video\n          ref={video}\n          src={reel.videoUrl}\n          poster={reel.coverImageUrl ? sized(reel.coverImageUrl, 720) : undefined}\n          muted={!sound}\n          loop\n          playsInline\n          preload={active ? \"auto\" : \"metadata\"}\n          onTimeUpdate={(e) => {\n            const v = e.currentTarget;\n            const f = v.duration ? v.currentTime / v.duration : 0;\n            setProgress(f);\n            if (active) {\n              // It loops: jumping back to the start after the end means it played through\n              if (v.duration && last.current > v.duration - 1.5 && v.currentTime < 1) playedThrough();\n              last.current = v.currentTime;\n              watched.current.seconds = Math.max(watched.current.seconds, v.currentTime);\n              // It loops: once it has played through, it counts as finished\n              watched.current.max = Math.max(watched.current.max, f, v.played.length && v.played.end(v.played.length - 1) >= v.duration - 0.5 ? 1 : 0);\n            }\n          }}\n          onEnded={() => trackContent(reel.id, \"complete\")}\n          onLoadedMetadata={shape.measure}\n          onClick={onToggleSound}\n                    className={`absolute inset-0 h-full w-full ${fill ? \"object-cover\" : \"object-contain\"}`}\n        />\n      ) : (\n        (reel.coverImageUrl || yt) && (\n          <Photo src={reel.coverImageUrl || youtubeThumb(yt!)} eager className={`absolute inset-0 h-full w-full ${fill ? \"object-cover\" : \"object-contain\"}`} />\n        )\n      )}\n      <div className=\"pointer-events-none absolute inset-0 bg-gradient-to-t from-black/80 via-black/0 to-black/30\" />\n\n      {/* Buttons on the right, like Reels */}\n      <div className=\"absolute bottom-28 right-3 flex flex-col items-center gap-5 pb-[env(safe-area-inset-bottom)]\">\n        <RailButton label={t(liked ? \"Helped ✓\" : \"This helped\")} onClick={() => triedStore.toggleLike(reel.id)}>\n          <Heart size={28} className={liked ? \"text-red-500\" : \"\"} fill={liked ? \"currentColor\" : \"none\"} />\n        </RailButton>\n        <RailButton\n          label={t(saved ? \"Saved\" : \"Save\")}\n          onClick={() => {\n            const now = socialStore.toggleBookmark(reel.id);\n            if (now) trackContent(reel.id, \"save\");\n            showToast(t(now ? \"Saved to your playbook\" : \"Removed from your playbook\"));\n          }}\n        >\n          <Bookmark size={26} fill={saved ? \"currentColor\" : \"none\"} />\n        </RailButton>\n        <RailButton label={t(\"Share\")} onClick={() => setSharing(true)}>\n          <Send size={25} />\n        </RailButton>\n        <RailButton\n          label={t(done ? \"Done ✓\" : \"I did it\")}\n          onClick={() => {\n            const now = triedStore.toggleDone(reel.id, done);\n            if (now) {\n              haptic(\"done\");\n              trackContent(reel.id, \"complete\");\n              showToast(t(\"Nice one, bro. Keep going.\"));\n            }\n          }}\n        >\n          <Check size={27} className={done ? \"text-mint\" : \"\"} strokeWidth={done ? 3 : 2} />\n        </RailButton>\n      </div>\n\n      {/* Caption */}\n      <div className=\"absolute inset-x-0 bottom-0 px-4 pb-[max(1.5rem,env(safe-area-inset-bottom))] pr-20\">\n        <p className=\"text-[0.8125rem] font-bold text-white/90\">@kayaniherbs</p>\n        <p className=\"mt-1 font-display text-[1.125rem] font-bold leading-snug\">{title}</p>\n        <ReelCaption text={caption} dark className=\"mt-1 max-h-[45dvh] overflow-y-auto overscroll-contain text-[0.875rem] leading-snug\" />\n        <Link href={contentHref(reel.id)} onClick={onLeave} className=\"mt-2.5 inline-flex items-center gap-1.5 rounded-full bg-white/15 px-3.5 py-1.5 text-xs font-bold backdrop-blur\">\n          {t(\"Full page\")} <ArrowRight size={13} />\n        </Link>\n      </div>\n      <div className=\"absolute inset-x-0 bottom-0 h-0.5 bg-white/20\">\n        <div className=\"h-full bg-white\" style={{ width: `${progress * 100}%` }} />\n      </div>\n      <ShareSheet open={sharing} onClose={() => setSharing(false)} item={reel} spec={reel.action} above t={t} />\n    </section>\n  );\n}\n\nfunction RailButton({ label, onClick, children }: { label: string; onClick: () => void; children: React.ReactNode }) {\n  return (\n    <button type=\"button\" onClick={onClick} aria-label={label} className=\"flex flex-col items-center gap-1 text-white drop-shadow transition-transform active:scale-90\">\n      {children}\n      <span className=\"max-w-[4.5rem] text-center text-[0.625rem] font-semibold leading-tight\">{label}</span>\n    </button>\n  );\n}\n","src/components/social/ContentDetail.tsx":"\"use client\";\n\nimport { sized } from \"@/lib/media/image\";\nimport Photo from \"@/components/media/Photo\";\nimport { useEffect, useRef, useState } from \"react\";\nimport Link from \"next/link\";\nimport { ArrowLeft, Check, ExternalLink, MessageCircle, PlayCircle, ShieldCheck } from \"lucide-react\";\nimport Cover from \"./Cover\";\nimport BookmarkButton from \"./BookmarkButton\";\nimport { SaveGuideButton } from \"@/components/offline/SaveButtons\";\nimport { useDownloads } from \"@/lib/offline/downloads\";\nimport { ContentRow } from \"./ContentCards\";\nimport { DoctorCheck, PelvicFloorTrainer, QuizRunner } from \"./ContentTools\";\nimport { useToast } from \"@/components/motion/Toast\";\nimport { useLibrary } from \"@/lib/content/useLibrary\";\nimport { useLang, type Lang } from \"@/lib/me/lang\";\nimport { getContent } from \"@/lib/content/select\";\nimport { feedStore, useFeed } from \"@/lib/feed/store\";\nimport { socialStore } from \"@/lib/social/store\";\nimport { useT } from \"@/lib/i18n\";\nimport { metaOf, topicTitle } from \"@/lib/content/display\";\nimport { trackContent } from \"@/lib/analytics/track\";\nimport { isYouTubeShort, youtubeId } from \"@/lib/content/youtube\";\nimport { YouTubeFrame } from \"@/components/media/YouTubeFrame\";\nimport ShapedVideo from \"@/components/media/ShapedVideo\";\nimport { UPRIGHT, WIDE } from \"@/lib/media/videoShape\";\nimport { useAccount } from \"@/lib/account/useAccount\";\nimport GuestGuideCard from \"@/components/account/GuestGuideCard\";\nimport ListenButton from \"./ListenButton\";\nimport KitoMark from \"@/components/kito/KitoMark\";\nimport { openKito } from \"@/components/kito/KitoLauncher\";\nimport { actionOf } from \"@/lib/content/actions\";\n\n/** Full page for any piece of content: guide, article, video, quiz, tool or expert answer. */\nexport default function ContentDetail({ id, back }: { id: string; back: { href: string; label: string } }) {\n  const library = useLibrary();\n  // A guide saved for offline still opens when it's no longer in the content list on this phone (Step 67)\n  const saved = useDownloads().items[id];\n  const item = getContent(id, library.items) ?? (saved?.kind === \"guide\" ? (saved.item ?? null) : null);\n  const feed = useFeed();\n  const acc = useAccount();\n  const showToast = useToast();\n  const t = useT();\n  // Opens in the language he chose (Me tab); he can still switch on the page\n  const appLang = useLang();\n  const [picked, setLang] = useState<Lang | null>(null);\n  const lang = picked ?? appLang;\n  // Reading completion: he scrolled to the end of a guide, article or answer\n  const endRef = useRef<HTMLParagraphElement>(null);\n  const readable = item ? [\"guide\", \"article\", \"expert\", \"infographic\"].includes(item.kind) : false;\n  useEffect(() => {\n    const el = endRef.current;\n    if (!el || !readable || typeof IntersectionObserver === \"undefined\") return;\n    const io = new IntersectionObserver((entries) => {\n      if (entries.some((e) => e.isIntersecting)) {\n        trackContent(id, \"complete\");\n        io.disconnect();\n      }\n    });\n    io.observe(el);\n    return () => io.disconnect();\n  }, [id, readable]);\n  // Remember he opened it, so Discover can suggest things he hasn't read yet\n  const found = Boolean(item);\n  useEffect(() => {\n    if (!found) return;\n    socialStore.recordOpen(id);\n    trackContent(id, \"view\");\n  }, [found, id]);\n\n  if (!item && !library.ready) {\n    return (\n      <div className=\"space-y-4\" aria-busy=\"true\" aria-label={t(\"Loading\")}>\n        <div className=\"aspect-[16/9] animate-pulse rounded-[28px] bg-forest-deep/15\" />\n        <div className=\"h-7 w-3/4 animate-pulse rounded-full bg-line\" />\n        <div className=\"h-40 animate-pulse rounded-3xl bg-surface ring-1 ring-line\" />\n      </div>\n    );\n  }\n\n  if (!item) {\n    return (\n      <div className=\"space-y-4\">\n        <Link href={back.href} className=\"flex items-center gap-1 text-sm text-ink-soft\">\n          <ArrowLeft size={16} /> {t(back.label)}\n        </Link>\n        <div className=\"rounded-3xl bg-surface p-8 text-center ring-1 ring-line\">\n          <p className=\"font-semibold\">{t(\"This content isn't available\")}</p>\n          <p className=\"mt-1 text-sm text-ink-soft\">{t(\"It may have been moved or removed.\")}</p>\n          <Link href=\"/social\" className=\"mt-4 inline-block rounded-full bg-forest px-5 py-2.5 text-sm font-semibold text-white\">\n            {t(\"Go to Discover\")}\n          </Link>\n        </div>\n      </div>\n    );\n  }\n\n  const sw = lang === \"sw\" && Boolean(item.bodySw);\n  const title = lang === \"sw\" && item.titleSw ? item.titleSw : item.title;\n  const yt = youtubeId(item.videoUrl);\n  const upright = item.kind === \"reel\" || isYouTubeShort(item.videoUrl);\n  const body = sw ? item.bodySw : item.body;\n  const read = Boolean(feed.lessons[item.id]);\n  const related = library.items.filter((c) => c.topic === item.topic && c.id !== item.id)\n    .sort((a, b) => b.priority - a.priority)\n    .slice(0, 3);\n\n  return (\n    <article className=\"stagger space-y-5\">\n      <div className=\"flex items-center justify-between\">\n        <Link href={back.href} className=\"flex items-center gap-1 text-sm text-ink-soft\">\n          <ArrowLeft size={16} /> {t(back.label)}\n        </Link>\n        <div className=\"flex items-center gap-2\">\n          <SaveGuideButton item={item} href={`/social/c/${item.id}`} />\n          <BookmarkButton contentId={item.id} />\n        </div>\n      </div>\n\n      <div className=\"overflow-hidden rounded-[28px]\">\n        {yt && (item.kind === \"reel\" || item.kind === \"video\" || item.action) ? (\n          // A YouTube video (Step 74): plays right here, with YouTube's own buttons\n          <YouTubeFrame\n            id={yt}\n            controls\n            title={title}\n            onEnded={() => trackContent(item.id, \"complete\")}\n            className={upright ? \"mx-auto aspect-[9/16] max-h-[78dvh] w-full\" : \"aspect-video w-full\"}\n          />\n        ) : item.kind === \"reel\" && item.videoUrl ? (\n          // A reel (Step 70): in the shape it was filmed (Step 92), as tall as the screen allows\n          <ShapedVideo\n            src={item.videoUrl}\n            fallback={UPRIGHT}\n            poster={item.coverImageUrl ? sized(item.coverImageUrl, 720) : undefined}\n            controls\n            playsInline\n            preload=\"metadata\"\n            onEnded={() => trackContent(item.id, \"complete\")}\n            className=\"rounded-[inherit]\"\n          />\n        ) : item.kind === \"video\" && item.videoUrl ? (\n          <ShapedVideo\n            src={item.videoUrl}\n            fallback={WIDE}\n            poster={item.coverImageUrl ? sized(item.coverImageUrl, 720) : undefined}\n            controls\n            playsInline\n            preload=\"metadata\"\n            onEnded={() => trackContent(item.id, \"complete\")}\n            className=\"rounded-[inherit]\"\n          />\n        ) : item.kind === \"infographic\" && item.coverImageUrl ? (\n          <Photo src={item.coverImageUrl} alt={title} eager className=\"w-full bg-surface\" />\n        ) : item.kind === \"audio\" ? (\n          <div className=\"space-y-3 bg-forest-deep p-4\">\n            <Cover item={item} className=\"aspect-[2/1] w-full rounded-2xl\" showPlay={false} />\n            {item.audioUrl ? (\n              <audio src={item.audioUrl} controls preload=\"metadata\" onEnded={() => trackContent(item.id, \"complete\")} className=\"w-full\" />\n            ) : (\n              <p className=\"text-center text-sm text-mint\">{t(\"Audio coming soon\")}</p>\n            )}\n          </div>\n        ) : item.action && item.videoUrl ? (\n          <ShapedVideo src={item.videoUrl} poster={item.coverImageUrl ? sized(item.coverImageUrl, 720) : undefined} controls playsInline preload=\"metadata\" className=\"rounded-[inherit]\" />\n        ) : item.action && item.audioUrl ? (\n          <div className=\"space-y-3 bg-forest-deep p-4\">\n            <Cover item={item} className=\"aspect-[2/1] w-full rounded-2xl\" showPlay={false} />\n            <audio src={item.audioUrl} controls preload=\"metadata\" className=\"w-full\" />\n          </div>\n        ) : item.kind === \"video\" ? (\n          <div className=\"relative\">\n            <Cover item={item} className=\"aspect-video w-full\" showPlay={false} />\n            <div className=\"absolute inset-0 flex flex-col items-center justify-center gap-2 bg-black/30 text-white\">\n              <PlayCircle size={44} />\n              <p className=\"text-sm font-semibold\">{t(\"Video coming soon\")}</p>\n              <p className=\"text-xs text-white/80\">{t(\"Key points are below\")}</p>\n            </div>\n          </div>\n        ) : (\n          <Cover item={item} className=\"aspect-[16/9] w-full\" />\n        )}\n      </div>\n\n      <header>\n        <p className=\"text-[0.6875rem] font-semibold uppercase tracking-wider text-forest\">\n          <Link href={`/social/topic/${item.topic}`} className=\"underline-offset-2 hover:underline\">\n            {topicTitle(item.topic, t)}\n          </Link>{\" \"}\n          · {metaOf(item, t)}\n        </p>\n        <h1 className=\"mt-2 text-[1.625rem] font-bold leading-tight\">{title}</h1>\n        {(lang !== \"sw\" || item.summarySw) && <p className=\"mt-2 text-[0.9375rem] leading-relaxed text-ink-soft\">{lang === \"sw\" && item.summarySw ? item.summarySw : item.summary}</p>}\n        {/* Step 90: hear it read aloud, or ask Kito about it */}\n        <div className=\"mt-3 flex flex-wrap gap-2\">\n          <ListenButton item={item} spec={actionOf(item)} big />\n          <button\n            type=\"button\"\n            onClick={() => openKito({ id: item.id, title })}\n            className=\"flex items-center gap-2 rounded-full py-1 pl-1 pr-4 text-sm font-bold text-forest ring-1 ring-line transition-transform active:scale-95\"\n          >\n            <KitoMark size={30} /> {t(\"Ask Kito about this\")}\n          </button>\n        </div>\n        <p className=\"mt-3 flex items-start gap-1.5 rounded-2xl bg-bg px-3 py-2 text-[0.6875rem] leading-snug text-ink-soft ring-1 ring-line\">\n          <ShieldCheck size={13} className=\"mt-px shrink-0 text-forest\" />\n          <span>\n            {item.source}\n            {item.fixture && ` · ${t(\"Sample content for development\")}`}\n          </span>\n        </p>\n        {(item.bodySw || item.origin) && (\n          <div className=\"mt-3 flex items-center justify-between gap-2\">\n            {item.bodySw ? (\n              <div className=\"inline-flex rounded-full bg-surface p-1 text-xs font-semibold ring-1 ring-line\" role=\"tablist\" aria-label={t(\"Language\")}>\n                {([\"en\", \"sw\"] as const).map((l) => (\n                  <button\n                    key={l}\n                    role=\"tab\"\n                    aria-selected={lang === l}\n                    onClick={() => setLang(l)}\n                    className={`rounded-full px-3 py-1.5 ${lang === l ? \"bg-forest text-white\" : \"text-ink-soft\"}`}\n                  >\n                    {l === \"en\" ? \"English\" : \"Kiswahili\"}\n                  </button>\n                ))}\n              </div>\n            ) : (\n              <span />\n            )}\n            {item.origin && (\n              <a\n                href={item.origin.url}\n                target=\"_blank\"\n                rel=\"noopener noreferrer\"\n                className=\"flex items-center gap-1 text-xs font-semibold text-forest\"\n              >\n                {t(item.origin.format === \"reel\" ? \"Watch on Instagram\" : \"View on Instagram\")} <ExternalLink size={12} />\n              </a>\n            )}\n          </div>\n        )}\n      </header>\n\n      {item.kind === \"expert\" && item.question && (\n        <blockquote className=\"flex gap-3 rounded-3xl bg-mint/60 p-4\">\n          <MessageCircle size={18} className=\"mt-0.5 shrink-0 text-forest\" />\n          <p className=\"text-sm font-medium italic text-forest-deep\">&ldquo;{item.question}&rdquo;</p>\n        </blockquote>\n      )}\n\n      {body && (\n        <div lang={sw ? \"sw\" : \"en\"} className=\"space-y-3 rounded-3xl bg-surface p-5 text-[0.9375rem] leading-relaxed ring-1 ring-line\">\n          {body.map((p, i) =>\n            p.startsWith(\"## \") ? (\n              <h2 key={i} className=\"pt-2 text-lg font-bold\">\n                {p.slice(3)}\n              </h2>\n            ) : (\n              <p key={i}>{p}</p>\n            ),\n          )}\n        </div>\n      )}\n\n      {item.keyPoints && (\n        <div className=\"rounded-3xl bg-surface p-5 ring-1 ring-line\">\n          <h2 className=\"font-bold\">{t(\"Key points\")}</h2>\n          <ol className=\"mt-3 space-y-2\">\n            {item.keyPoints.map((k, i) => (\n              <li key={i} className=\"flex gap-3 text-sm\">\n                <span className=\"flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-mint text-xs font-bold text-forest\">\n                  {i + 1}\n                </span>\n                {k}\n              </li>\n            ))}\n          </ol>\n        </div>\n      )}\n\n      {item.quiz && <QuizRunner questions={item.quiz} onFinish={() => trackContent(item.id, \"complete\")} />}\n      {item.tool === \"pelvic-floor\" && <PelvicFloorTrainer />}\n      {item.tool === \"doctor-check\" && <DoctorCheck />}\n\n      {/* Points need an account (the Man tab is for members); guests get the invite card instead */}\n      {item.inManFeed && feed.ready && acc.status !== \"guest\" && (\n        <button\n          onClick={() => {\n            if (read) return;\n            feedStore.markLessonRead(item.id);\n            trackContent(item.id, \"complete\");\n            showToast(t(\"Lesson read · +{n} points\", { n: item.points ?? 10 }));\n          }}\n          className={`flex w-full items-center justify-center gap-2 rounded-full py-3.5 text-sm font-semibold transition-transform active:scale-[0.98] ${\n            read ? \"bg-mint text-forest\" : \"bg-forest text-white\"\n          }`}\n        >\n          {read ? (\n            <>\n              <Check size={16} /> {t(\"You've read this\")}\n            </>\n          ) : (\n            t(\"Mark as read · +{n} points\", { n: item.points ?? 10 })\n          )}\n        </button>\n      )}\n\n      {/* Marks the end of the page, for \"he read it all\" */}\n      <p ref={endRef} aria-hidden className=\"h-px\" />\n\n      <GuestGuideCard next={`/social/c/${item.id}`} />\n\n      {related.length > 0 && (\n        <section className=\"space-y-3 pt-2\">\n          <h2 className=\"text-base font-bold\">{t(\"More on {topic}\", { topic: topicTitle(item.topic, t).toLowerCase() })}</h2>\n          {related.map((r) => (\n            <ContentRow key={r.id} item={r} />\n          ))}\n        </section>\n      )}\n    </article>\n  );\n}\n","src/components/social/ActionFeed.tsx":"\"use client\";\n\n// Discover as a feed of things to DO, not things to read about.\n// Top: \"What are you dealing with?\" circles, like Instagram stories. Below: one endless column of\n// action cards. Each card is a carousel he swipes through: the hook, what he needs, the steps,\n// why it works. Then: \"Useful\", share, save, and \"I did it\".\n\nimport { sized } from \"@/lib/media/image\";\nimport { CIRCLES, circlesOf } from \"@/lib/content/circles\";\nimport { haptic } from \"@/lib/motion/haptics\";\nimport { flyPoints } from \"@/lib/motion/flyPoints\";\nimport { Fragment, useCallback, useEffect, useMemo, useRef, useState } from \"react\";\nimport Link from \"next/link\";\nimport {\n  ArrowRight,\n  BatteryCharging,\n  BookOpen,\n  Bookmark,\n  Brain,\n  Check,\n  ChevronLeft,\n  ChevronRight,\n  Dumbbell,\n  Flame,\n  Hand,\n  Heart,\n  Layers,\n  Leaf,\n  MessageCircle,\n  Moon,\n  Send,\n  Sparkles,\n  Timer,\n  Zap,\n} from \"lucide-react\";\nimport Cover from \"./Cover\";\nimport { contentHref } from \"./ContentCards\";\nimport { useToast } from \"@/components/motion/Toast\";\nimport { useLibrary } from \"@/lib/content/useLibrary\";\nimport { actionOf } from \"@/lib/content/actions\";\nimport type { ActionResult, ActionSpec, ActionType, ChallengeId, ContentItem } from \"@/lib/content/types\";\nimport { socialStore, useSocial } from \"@/lib/social/store\";\nimport { TRIED_POINTS, triedStore, useTried, type FeedFilter } from \"@/lib/social/tried\";\nimport { helpedYes } from \"@/lib/social/helped\";\nimport { useFeed } from \"@/lib/feed/store\";\nimport HelpedCheck from \"./HelpedCheck\";\nimport { trackContent } from \"@/lib/analytics/track\";\nimport { youtubeId } from \"@/lib/content/youtube\";\nimport { YouTubeFrame } from \"@/components/media/YouTubeFrame\";\nimport { inviteToAccount } from \"@/components/account/AccountInvite\";\nimport { useT, type T } from \"@/lib/i18n\";\nimport { ReelPost, ReelsViewer } from \"./Reels\";\nimport { openKito } from \"@/components/kito/KitoLauncher\";\nimport KitoMark from \"@/components/kito/KitoMark\";\nimport { isReel } from \"@/lib/content/reels\";\nimport { hash, orderCards, orderReels, placeReels, reelEvery, type Habits } from \"@/lib/content/discover\";\nimport { challengeDates, dropCards, dropTimes, seriesOf, seriesOpen, seriesProgress } from \"@/lib/content/hooks\";\nimport { isCircle } from \"@/lib/content/circles\";\nimport { topicQueue } from \"@/lib/content/reels\";\nimport { useProgress } from \"@/lib/progress/store\";\nimport { useSaveData } from \"@/lib/media/saveData\";\nimport ListenButton from \"./ListenButton\";\nimport { dateKey, shiftKey } from \"@/lib/progress/dates\";\nimport { thenAndNow, THEN_NOW_EVERY_DAYS, type ThenNow } from \"@/lib/progress/thenNow\";\nimport { helpedShown, storyFor, useStories } from \"@/lib/social/stories\";\nimport { AskSlide, ChallengeButton, ChallengeStrip, DropBanner, LockedPart, NextPartSlide, ShareSheet, StoryCard, ThenNowCard, type SeriesInfo } from \"./Hooks\";\nimport { DISCOVER_REFRESH, habitsStore, useDiscoverConfig, visitSeed } from \"@/lib/social/discoverPrefs\";\nimport { useAccount } from \"@/lib/account/useAccount\";\n\n// The circles: names from the shared list (lib/content/circles.ts), so the Studio uses the very same ones (Step 80)\nconst ICON: Record<ChallengeId, typeof Timer> = { last: Timer, hard: Zap, her: Flame, mixes: Leaf, train: Dumbbell, reset: Brain, desire: BatteryCharging };\nconst CHALLENGES: { id: FeedFilter; label: string; icon: typeof Timer }[] = [\n  { id: \"all\", label: \"For you\", icon: Sparkles },\n  ...CIRCLES.map((c) => ({ id: c.id, label: c.label, icon: ICON[c.id] })),\n];\n\nconst TYPE_LABEL: Record<ActionType, string> = {\n  technique: \"Technique\",\n  position: \"Positions\",\n  mix: \"Natural mix\",\n  exercise: \"Exercise\",\n  food: \"Food\",\n  habit: \"Daily habit\",\n  mind: \"Mindset\",\n};\n\nconst RESULT_LABEL: Record<ActionResult, string> = {\n  tonight: \"Works tonight\",\n  days: \"Results in days\",\n  weeks2: \"Feel it in 1–3 weeks\",\n  weeks4: \"Feel it in 3–6 weeks\",\n  daily: \"Daily habit\",\n};\n\nconst TYPE_ICON: Record<ActionType, typeof Timer> = {\n  technique: Flame,\n  position: Heart,\n  mix: Leaf,\n  exercise: Dumbbell,\n  food: Leaf,\n  habit: Moon,\n  mind: Brain,\n};\n\nconst PAGE = 8;\nconst TIMER_ID = \"tool-pelvic-floor\";\n\ntype Card = { item: ContentItem; spec: ActionSpec };\n\nexport function ActionFeedSkeleton() {\n  const t = useT();\n  return (\n    <div className=\"space-y-5\" aria-busy=\"true\" aria-label={t(\"Loading\")}>\n      <div className=\"flex gap-4 overflow-hidden\">\n        {[0, 1, 2, 3, 4].map((i) => (\n          <div key={i} className=\"h-[68px] w-[68px] shrink-0 animate-pulse rounded-full bg-line\" />\n        ))}\n      </div>\n      <div className=\"aspect-[5/4] animate-pulse rounded-[20px] bg-forest-deep/15 lg:mx-0\" />\n    </div>\n  );\n}\n\ntype Visit = {\n  seed: string;\n  done: Record<string, string>;\n  /** card id → his date he did it (for series parts) */\n  doneOn: Record<string, string>;\n  opened: Record<string, string>;\n  saved: Record<string, string>;\n  habits: Habits;\n  today: string;\n  thenNow: ThenNow | null;\n};\n\nconst THEN_NOW_KEY = \"ms_then_now_seen\";\n\n/** Is it time for \"You, then and now\" (at most once a week; it stays for the rest of that day)? */\nfunction thenNowDue(today: string): boolean {\n  try {\n    const seen = localStorage.getItem(THEN_NOW_KEY);\n    if (seen === `x:${today}`) return false; // he closed it today\n    return !seen || seen === today || seen < shiftKey(today, -THEN_NOW_EVERY_DAYS);\n  } catch {\n    return false;\n  }\n}\nfunction thenNowMark(v: string) {\n  try {\n    localStorage.setItem(THEN_NOW_KEY, v);\n  } catch {}\n}\n\nexport default function ActionFeed() {\n  const { items } = useLibrary();\n  const feed = useFeed();\n  const tried = useTried();\n  const social = useSocial();\n  const progress = useProgress();\n  const { stories, counts } = useStories();\n  const t = useT();\n  const sw = t.lang === \"sw\";\n  const [shown, setShown] = useState(PAGE);\n  // Reels (Step 70): the order is fixed when the viewer opens, so it doesn't move while he watches\n  const [viewer, setViewer] = useState<{ list: ContentItem[]; start: number; sound: boolean } | null>(null);\n  const top = useRef<HTMLDivElement>(null);\n  const filter = tried.filter;\n  const circle: ChallengeId | null = isCircle(filter) ? filter : null;\n\n  const acc = useAccount();\n  const cfg = useDiscoverConfig();\n  const accountId = acc.status === \"signedIn\" ? acc.user.id : null;\n\n  // Every \"do this\" card (built-in and from the Studio's Card maker)\n  const all = useMemo<Card[]>(\n    () =>\n      items.flatMap((item) => {\n        const spec = actionOf(item);\n        return spec && item.status !== \"archived\" ? [{ item, spec }] : [];\n      }),\n    [items],\n  );\n  const seriesMap = useMemo(() => seriesOf(all), [all]);\n\n  // Step 71: a new order every visit, different for each man. What he did, opened and his habits are\n  // read once when the visit starts (or he changes the challenge), so nothing jumps while he scrolls.\n  const [refreshes, setRefreshes] = useState(0);\n  const [visit, setVisit] = useState<Visit | null>(null);\n  useEffect(() => {\n    if (!tried.ready || !social.ready || !progress.ready) return;\n    const today = dateKey(new Date());\n    const doneOn: Record<string, string> = {};\n    for (const [id, at] of Object.entries(tried.done)) doneOn[id] = feed.tried?.[id]?.localDate ?? dateKey(new Date(at));\n    // Step 86: \"You, then and now\", from his own records and what he did\n    const doneDates = [...Object.values(doneOn), ...challengeDates(feed.challenges)];\n    const tn = cfg.thenNow && thenNowDue(today) ? thenAndNow(progress.records, doneDates, today) : null;\n    setVisit({ seed: visitSeed(accountId), done: { ...tried.done }, doneOn, opened: { ...social.history }, saved: { ...social.bookmarks }, habits: habitsStore.get(), today, thenNow: tn });\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [tried.ready, social.ready, progress.ready, filter, accountId, refreshes]);\n  // Pull to refresh (Step 77) starts a new visit: a fresh order, from the top\n  useEffect(() => {\n    const on = () => {\n      setShown(PAGE);\n      setRefreshes((n) => n + 1);\n    };\n    window.addEventListener(DISCOVER_REFRESH, on);\n    return () => window.removeEventListener(DISCOVER_REFRESH, on);\n  }, []);\n\n  const notHelped = useMemo(() => {\n    const out: Record<string, string> = {};\n    for (const [id, x] of Object.entries(feed.tried ?? {})) if (x?.helped?.answer === \"no\") out[id] = x.helped.at;\n    return out;\n  }, [feed.tried]);\n\n  // What this view shows (Step 86: his playbook and series too). Later parts of a series stay hidden until they open.\n  const view = useMemo(() => {\n    const empty = { cards: [] as Card[], locked: [] as { part: number; total: number; opensOn: string | null }[] };\n    if (!visit) return empty;\n    const open = (c: Card) => seriesOpen(c, seriesMap, visit.doneOn, visit.today, cfg.seriesWait);\n    if (filter === \"saved\") {\n      const saved = all.filter((c) => visit.saved[c.item.id]);\n      saved.sort((a, b) => Number(Boolean(visit.done[a.item.id])) - Number(Boolean(visit.done[b.item.id])) || visit.saved[b.item.id].localeCompare(visit.saved[a.item.id]));\n      return { ...empty, cards: saved };\n    }\n    if (filter.startsWith(\"series:\")) {\n      const s = seriesMap.get(filter.slice(7));\n      if (!s) return empty;\n      const cards = s.parts.filter(open);\n      const pr = seriesProgress(s, visit.doneOn, visit.today, cfg.seriesWait);\n      const locked = s.parts.filter((c) => !open(c)).map((c, i) => ({ part: c.spec.series!.part, total: s.parts.length, opensOn: i === 0 ? pr.opensOn : null }));\n      return { cards, locked };\n    }\n    const picked = (filter === \"all\" ? all : all.filter((c) => circle && c.spec.challenges.includes(circle))).filter(open);\n    const taste = {\n      interests: social.interests,\n      opened: visit.opened,\n      liked: { ...helpedYes(feed.tried), ...tried.liked },\n      done: visit.done,\n      saved: visit.saved,\n      notHelped,\n      nextParts: new Set(\n        [...seriesMap.values()].flatMap((s) => {\n          const p = seriesProgress(s, visit.doneOn, visit.today, cfg.seriesWait);\n          return p.started && p.next && !p.opensOn ? [p.next.item.id] : [];\n        }),\n      ),\n    };\n    return { ...empty, cards: orderCards(picked, `${visit.seed}:${filter}`, taste, cfg) };\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [all, filter, visit, cfg, seriesMap]);\n  const cards = view.cards;\n  const plain = filter === \"all\" || Boolean(circle);\n\n  const reels = useMemo(() => (visit ? orderReels(items.filter(isReel), visit.seed, visit.opened, cfg) : []), [items, visit, cfg]);\n  // Reels inside the feed: how often depends on the Studio setting and (if allowed) on his habits\n  // Step 80: inside a circle, only the reels staff put in that circle\n  const reelSpots = useMemo(() => {\n    if (!visit || !plain) return new Map<number, ContentItem>();\n    const here = filter === \"all\" ? reels : reels.filter((r) => circle && circlesOf(r).includes(circle));\n    return placeReels(cards.length, here, reelEvery(cfg, visit.habits));\n  }, [visit, filter, circle, plain, reels, cards.length, cfg]);\n\n  // Step 86: the daily drop — Studio cards that went live since the last drop time, not opened yet\n  const [now] = useState(() => new Date());\n  const drop = useMemo(() => {\n    if (!visit || filter !== \"all\") return { fresh: [] as Card[], next: null as Date | null };\n    const fresh = dropCards(cards, cfg.dropAt || null, now).filter((c) => !visit.opened[c.item.id] && !visit.done[c.item.id]);\n    return { fresh, next: cfg.dropAt ? (dropTimes(cfg.dropAt, now)?.next ?? null) : null };\n  }, [visit, filter, cards, cfg.dropAt, now]);\n  const goToDrop = useCallback(() => {\n    const id = drop.fresh[0]?.item.id;\n    if (id) document.querySelector(`[data-card=\"${id}\"]`)?.scrollIntoView({ behavior: \"smooth\", block: \"start\" });\n  }, [drop.fresh]);\n  // Opened from the drop notification: straight to the new cards\n  const dropLink = useRef(false);\n  useEffect(() => {\n    if (dropLink.current || !drop.fresh.length) return;\n    if (!/[?&]drop=1/.test(location.search)) return;\n    dropLink.current = true;\n    requestAnimationFrame(goToDrop);\n  }, [drop.fresh, goToDrop]);\n\n  // Series he's in the middle of: circles at the top (Step 86)\n  const seriesCircles = useMemo(() => {\n    if (!visit) return [];\n    return [...seriesMap.values()]\n      .map((s) => ({ s, p: seriesProgress(s, visit.doneOn, visit.today, cfg.seriesWait) }))\n      .filter((x) => x.p.started && !x.p.finished)\n      .sort((a, b) => Number(Boolean(a.p.opensOn)) - Number(Boolean(b.p.opensOn)))\n      .slice(0, 4);\n  }, [seriesMap, visit, cfg.seriesWait]);\n\n  const [thenNowOpen, setThenNowOpen] = useState(true);\n  useEffect(() => {\n    if (visit?.thenNow) thenNowMark(visit.today);\n  }, [visit]);\n  const seedNum = visit ? hash(visit.seed) % 997 : 0;\n\n  // Load more cards as he nears the end\n  const sentinel = useRef<HTMLDivElement>(null);\n  const more = cards.length > shown;\n  useEffect(() => {\n    const el = sentinel.current;\n    if (!el || !more || typeof IntersectionObserver === \"undefined\") return;\n    const io = new IntersectionObserver((e) => e.some((x) => x.isIntersecting) && setShown((n) => n + PAGE), { rootMargin: \"800px 0px\" });\n    io.observe(el);\n    return () => io.disconnect();\n  }, [more, shown]);\n\n  const pick = (id: FeedFilter) => {\n    triedStore.setFilter(id === filter && id !== \"all\" ? \"all\" : id);\n    setShown(PAGE);\n    top.current?.scrollIntoView({ block: \"start\", behavior: \"smooth\" });\n  };\n\n  // Tapping a reel opens the full-screen viewer with sound on. The tapped reel comes first, then more reels\n  // on the same topic (Step 86), then the rest; pulling down on the first one closes the viewer (Step 77).\n  const openReels = (start: number, list = reels) => setViewer({ list: topicQueue(list, start, (r) => circlesOf(r)), start: 0, sound: true });\n  if (!tried.ready || !social.ready || !visit) return <ActionFeedSkeleton />;\n\n  const left = (id: ChallengeId | \"all\") => (id === \"all\" ? all : all.filter((c) => c.spec.challenges.includes(id))).some((c) => !tried.done[c.item.id]);\n  const savedCount = Object.keys(social.bookmarks).filter((id) => all.some((c) => c.item.id === id)).length;\n  const circles: { id: FeedFilter; label: string; icon: typeof Timer; fresh: boolean; ring?: number }[] = [\n    { ...CHALLENGES[0], fresh: left(\"all\") },\n    ...(savedCount ? [{ id: \"saved\" as FeedFilter, label: \"My playbook\", icon: BookOpen, fresh: false }] : []),\n    ...seriesCircles.map(({ s, p }) => ({\n      id: `series:${s.id}` as FeedFilter,\n      label: sw ? s.nameSw : s.name,\n      icon: Layers,\n      fresh: !p.opensOn,\n      ring: p.done / p.total,\n    })),\n    ...CHALLENGES.slice(1).map((c) => ({ ...c, fresh: left(c.id as ChallengeId) })),\n  ];\n  const current = circles.find((c) => c.id === filter) ?? circles[0];\n  const helpedFor = (id: string) => helpedShown(counts[id], Boolean(tried.liked[id]), cfg.helpedMin);\n  const seriesInfo = (c: Card): SeriesInfo | undefined => {\n    const sp = c.spec.series;\n    const s = sp && seriesMap.get(sp.id);\n    if (!sp || !s) return undefined;\n    const i = s.parts.findIndex((x) => x.item.id === c.item.id);\n    const next = s.parts[i + 1];\n    return {\n      name: sw ? s.nameSw : s.name,\n      part: i + 1,\n      total: s.parts.length,\n      tease: (sw ? sp.teaseSw : sp.tease) || (next ? (sw && next.item.titleSw ? next.item.titleSw : next.item.title) : undefined),\n      wait: cfg.seriesWait,\n      last: !next,\n    };\n  };\n\n  return (\n    <div className=\"mx-auto w-full max-w-[480px] space-y-4\">\n      <section aria-labelledby=\"challenge-h\" className=\"-mx-1 scroll-mt-4 lg:mx-0\" ref={top}>\n        <h2 id=\"challenge-h\" className=\"px-3.5 font-display text-[1.25rem] font-bold leading-tight lg:px-0\">\n          {t(\"What are you dealing with?\")}\n        </h2>\n        <div role=\"tablist\" aria-label={t(\"What are you dealing with?\")} className=\"no-scrollbar mt-3 flex gap-3.5 overflow-x-auto px-3.5 pb-1 lg:px-0\">\n          {circles.map(({ id, label, icon: Icon, fresh, ring }) => {\n            const on = filter === id;\n            // The ring is coloured while there are cards here he hasn't tried yet; a series shows how far he is\n            const bg =\n              ring !== undefined\n                ? { background: `conic-gradient(var(--honey) ${Math.round(ring * 360)}deg, var(--line) 0)` }\n                : undefined;\n            return (\n              <button\n                key={id}\n                role=\"tab\"\n                aria-selected={on}\n                onClick={() => pick(id)}\n                className=\"flex w-[74px] shrink-0 flex-col items-center gap-1.5 transition-transform active:scale-95\"\n              >\n                <span\n                  style={bg}\n                  className={`rounded-full p-[2.5px] ${ring !== undefined ? \"\" : fresh ? \"bg-[conic-gradient(from_200deg,var(--honey),var(--mint-strong),var(--forest),var(--honey))]\" : \"bg-line\"}`}\n                >\n                  <span className=\"block rounded-full bg-bg p-[2.5px]\">\n                    <span\n                      className={`flex h-[60px] w-[60px] items-center justify-center rounded-full transition-colors ${on ? \"bg-forest text-white\" : id === \"saved\" || ring !== undefined ? \"bg-honey/20 text-forest ring-1 ring-line\" : \"bg-surface text-forest ring-1 ring-line\"}`}\n                    >\n                      <Icon size={24} strokeWidth={2} aria-hidden />\n                    </span>\n                  </span>\n                </span>\n                <span className={`line-clamp-2 text-center text-[0.6875rem] leading-tight ${on ? \"font-bold text-ink\" : \"font-medium text-ink-soft\"}`}>\n                  {ring !== undefined ? label : t(label)}\n                </span>\n              </button>\n            );\n          })}\n        </div>\n      </section>\n\n      {/* Kito lives here on a phone, so his floating button doesn't have to sit on the cards (Step 73) */}\n      <button\n        type=\"button\"\n        onClick={() => openKito()}\n        data-kito-row\n        className=\"flex w-full items-center gap-2.5 rounded-full bg-surface py-1 pl-1 pr-4 text-left ring-1 ring-line transition-transform active:scale-[0.98] lg:hidden\"\n      >\n        <KitoMark size={36} />\n        <span className=\"flex-1 truncate text-sm text-ink-soft\">{t(\"Ask Kito…\")}</span>\n        <Send size={16} className=\"text-forest\" aria-hidden />\n      </button>\n\n      {/* Step 86: today's drop, and the challenges he's doing */}\n      {filter === \"all\" && <DropBanner fresh={drop.fresh.length} next={drop.next} onGo={goToDrop} t={t} />}\n      <ChallengeStrip items={items} t={t} />\n\n      {/* A few days after he did a card: did it help? (Step 79) */}\n      <HelpedCheck items={items} />\n\n      {filter !== \"all\" && (\n        <p className=\"edge-pad flex items-center justify-between gap-2 text-xs text-ink-soft\">\n          <span>\n            {filter === \"saved\"\n              ? t(\"My playbook: {n} saved, {d} done\", { n: cards.length, d: cards.filter((c) => tried.done[c.item.id]).length })\n              : filter.startsWith(\"series:\")\n                ? t(\"{name}: {d} of {total} parts done\", {\n                    name: current.label,\n                    d: cards.filter((c) => tried.done[c.item.id]).length,\n                    total: cards.length + view.locked.length,\n                  })\n                : t(\"{n} things to try for: {challenge}\", { n: cards.length, challenge: t(current.label).toLowerCase() })}\n          </span>\n          <button onClick={() => pick(\"all\")} className=\"font-semibold text-forest\">\n            {t(\"Show all\")}\n          </button>\n        </p>\n      )}\n\n      <div className=\"space-y-3 lg:mx-0 lg:space-y-4\">\n        {cards.slice(0, shown).map((c, i) => {\n          // Reels between the cards: full width, the one on screen plays silently (each reel shows once)\n          const r = reelSpots.get(i);\n          // A real man's story every few cards (Step 86)\n          const story = plain && cfg.storyEvery > 0 && i > 0 && i % cfg.storyEvery === 0 ? storyFor(stories, i / cfg.storyEvery - 1, circle, seedNum) : null;\n          return (\n            <Fragment key={`${filter}-${c.item.id}`}>\n              {r && <ReelPost reel={r} onOpen={() => openReels(reels.indexOf(r))} />}\n              {i === 2 && filter === \"all\" && visit.thenNow && thenNowOpen && (\n                <ThenNowCard\n                  data={visit.thenNow}\n                  t={t}\n                  onClose={() => {\n                    setThenNowOpen(false);\n                    thenNowMark(`x:${visit.today}`);\n                  }}\n                />\n              )}\n              {story && <StoryCard story={story} onCircle={(ch) => pick(ch)} t={t} />}\n              <ActionPost\n                card={c}\n                first={i === 0}\n                done={Boolean(tried.done[c.item.id])}\n                liked={Boolean(tried.liked[c.item.id])}\n                saved={Boolean(social.bookmarks[c.item.id])}\n                helped={helpedFor(c.item.id)}\n                series={seriesInfo(c)}\n              />\n            </Fragment>\n          );\n        })}\n        {view.locked.map((l) => (\n          <LockedPart key={l.part} part={l.part} total={l.total} opensOn={l.opensOn} t={t} />\n        ))}\n      </div>\n\n      {more ? (\n        <div ref={sentinel} className=\"h-[40vh] animate-pulse rounded-[20px] lg:mx-0 bg-surface ring-1 ring-line\" aria-hidden />\n      ) : (\n        <EndOfFeed filter={filter} empty={cards.length === 0} onPick={pick} t={t} />\n      )}\n      {viewer && <ReelsViewer reels={viewer.list} start={viewer.start} withSound={viewer.sound} onClose={() => setViewer(null)} />}\n    </div>\n  );\n}\n\nfunction EndOfFeed({ filter, empty, onPick, t }: { filter: FeedFilter; empty: boolean; onPick: (id: FeedFilter) => void; t: T }) {\n  if (filter === \"saved\" && empty) {\n    return (\n      <section className=\"rounded-[20px] bg-surface p-5 text-center ring-1 ring-line\">\n        <p className=\"font-display text-lg font-bold\">{t(\"Your playbook is empty\")}</p>\n        <p className=\"mt-1 text-sm text-ink-soft\">{t(\"Tap the bookmark on any card to keep it here, as your own plan.\")}</p>\n      </section>\n    );\n  }\n  if (filter.startsWith(\"series:\")) return null;\n  return (\n    <section className=\"rounded-[20px] bg-forest-deep p-5 text-center text-white\">\n      <p className=\"font-display text-xl font-bold\">{t(filter === \"saved\" ? \"That's your whole playbook\" : \"That's everything for now\")}</p>\n      <p className=\"mt-1 text-sm text-mint\">{t(\"Pick one you haven't done yet, and do it tonight.\")}</p>\n      <div className=\"mt-4 flex flex-wrap justify-center gap-2\">\n        {CHALLENGES.filter((c) => c.id !== filter && c.id !== \"all\")\n          .slice(0, 4)\n          .map((c) => (\n            <button key={c.id} onClick={() => onPick(c.id)} className=\"rounded-full bg-white/10 px-3.5 py-2 text-xs font-semibold text-white ring-1 ring-white/20\">\n              {t(c.label)}\n            </button>\n          ))}\n      </div>\n      <Link href=\"/social?tab=community\" className=\"mt-4 inline-flex items-center gap-1.5 text-sm font-semibold text-mint-strong\">\n        <MessageCircle size={15} /> {t(\"Ask the community\")}\n      </Link>\n    </section>\n  );\n}\n\n/** One card in the feed, Instagram-post style. Also used by the Studio's Card maker preview. */\nexport function ActionPost({\n  card,\n  first,\n  done,\n  liked,\n  saved,\n  helped = null,\n  series,\n}: {\n  card: Card;\n  first: boolean;\n  done: boolean;\n  liked: boolean;\n  saved: boolean;\n  /** \"N men said this helped\" (Step 86), or null to show nothing. */\n  helped?: number | null;\n  /** Where this card sits in its series (Step 86). */\n  series?: SeriesInfo;\n}) {\n  const { item, spec } = card;\n  const t = useT();\n  const sw = t.lang === \"sw\";\n  const showToast = useToast();\n  const title = sw && item.titleSw ? item.titleSw : item.title;\n  const hook = sw && item.summarySw ? item.summarySw : item.summary;\n  const why = sw ? spec.whySw : spec.why;\n  const need = sw ? spec.needSw : spec.need;\n  const TypeIcon = TYPE_ICON[spec.type];\n  const href = contentHref(item.id);\n  const [sharing, setSharing] = useState(false);\n\n  const slides: React.ReactNode[] = [\n    // Step 86: a question first, when the card has one (the answer is one tap away)\n    spec.ask ? (\n      <AskSlide key=\"ask\" ask={spec.ask} title={title} steps={spec.steps.length} t={t} onAnswer={habitsStore.cardUsed} />\n    ) : (\n      <HookSlide key=\"hook\" item={item} spec={spec} title={title} hook={hook} first={first} t={t} />\n    ),\n    ...(item.videoUrl || item.audioUrl ? [<MediaSlide key=\"media\" item={item} t={t} />] : []),\n    ...(need?.length ? [<NeedSlide key=\"need\" need={need} t={t} />] : []),\n    ...spec.steps.map((s, i) => (\n      <StepSlide key={`s${i}`} n={i + 1} total={spec.steps.length} title={sw ? s.titleSw : s.title} text={sw ? s.textSw : s.text} t={t} />\n    )),\n    ...(why ? [<WhySlide key=\"why\" why={why} t={t} />] : []),\n    ...(series ? [<NextPartSlide key=\"next\" s={series} t={t} />] : []),\n  ];\n\n  return (\n    <article data-card={item.id} className=\"scroll-mt-4 overflow-hidden rounded-[20px] bg-surface ring-1 ring-line\" aria-label={title}>\n      <header className=\"flex items-center gap-2.5 px-3 py-2\">\n        <span className=\"flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-mint text-forest\">\n          <TypeIcon size={16} aria-hidden />\n        </span>\n        <div className=\"min-w-0 flex-1\">\n          <p className=\"truncate text-[0.8125rem] font-bold leading-tight\">{series ? series.name : t(TYPE_LABEL[spec.type])}</p>\n          <p className=\"truncate text-[0.6875rem] text-ink-soft\">\n            {series ? `${t(\"Part {n} of {total}\", { n: series.part, total: series.total })} · ` : \"\"}\n            {t(\"{n} min\", { n: item.minutes })} · @kayaniherbs\n          </p>\n        </div>\n        <span\n          className={`shrink-0 rounded-full px-2.5 py-1 text-[0.6875rem] font-bold ${spec.results === \"tonight\" ? \"bg-honey text-on-honey\" : \"bg-mint text-forest\"}`}\n        >\n          {t(RESULT_LABEL[spec.results])}\n        </span>\n      </header>\n\n      <Carousel label={title} t={t} onSwipe={habitsStore.cardUsed}>\n        {slides}\n      </Carousel>\n\n      <div className=\"flex items-center px-1\">\n        <IconButton\n          label={t(liked ? \"Helped ✓\" : \"This helped\")}\n          pressed={liked}\n          onClick={() => {\n            const now = triedStore.toggleLike(item.id);\n            habitsStore.cardUsed();\n            if (now) showToast(t(\"Glad it helped\"));\n          }}\n        >\n          <Heart size={22} className={liked ? \"text-red-500\" : \"\"} fill={liked ? \"currentColor\" : \"none\"} />\n        </IconButton>\n        <IconButton label={t(\"Share\")} onClick={() => setSharing(true)}>\n          <Send size={21} />\n        </IconButton>\n        {/* Step 90: hear it, or ask Kito about this card */}\n        <ListenButton item={item} spec={spec} />\n        <IconButton label={t(\"Ask Kito about this\")} onClick={() => openKito({ id: item.id, title })}>\n          <KitoMark size={26} />\n        </IconButton>\n        <Link href={href} className=\"ml-0.5 flex items-center gap-1 rounded-full px-1.5 py-2 text-xs font-semibold text-ink-soft\">\n          {t(\"Full page\")} <ArrowRight size={13} />\n        </Link>\n        <span className=\"flex-1\" />\n        <IconButton\n          label={t(saved ? \"Remove from saved\" : \"Save for later\")}\n          pressed={saved}\n          onClick={() => {\n            const now = socialStore.toggleBookmark(item.id);\n            habitsStore.cardUsed();\n            if (now) trackContent(item.id, \"save\");\n            showToast(t(now ? \"Saved to your playbook\" : \"Removed from your playbook\"));\n            if (now) inviteToAccount(\"first-save\");\n          }}\n        >\n          <Bookmark size={21} fill={saved ? \"currentColor\" : \"none\"} />\n        </IconButton>\n      </div>\n\n      <div className=\"px-3 pb-3\">\n        {helped !== null && (\n          <p className=\"mb-1 flex items-center gap-1 text-xs font-semibold text-ink-soft\">\n            <Heart size={12} className=\"text-red-500\" fill=\"currentColor\" aria-hidden /> {t(helped === 1 ? \"1 man said this helped\" : \"{n} men said this helped\", { n: helped })}\n          </p>\n        )}\n        <p className=\"line-clamp-2 text-[0.875rem] font-bold leading-snug\">{title}</p>\n        <div className=\"mt-2 flex gap-2\">\n          <button\n            onClick={(e) => {\n              const now = triedStore.toggleDone(item.id, done);\n              habitsStore.cardUsed();\n              if (now) {\n                haptic(\"done\");\n                flyPoints(e.currentTarget, TRIED_POINTS); // Step 79: doing a card earns points\n                trackContent(item.id, \"complete\");\n                showToast(\n                  !series\n                    ? t(\"Nice one, bro. Keep going.\")\n                    : series.last\n                      ? t(\"Series finished. Respect.\")\n                      : t(series.wait ? \"Part {n} opens tomorrow.\" : \"Part {n} is open now.\", { n: series.part + 1 }),\n                );\n              }\n            }}\n            aria-pressed={done}\n            className={`flex flex-1 items-center justify-center gap-2 rounded-full py-2.5 text-sm font-bold transition-transform active:scale-[0.98] ${\n              done ? \"bg-mint text-forest\" : \"bg-forest text-white\"\n            }`}\n          >\n            {done ? (\n              <>\n                <Check size={16} /> {t(\"Done. Do it again anytime\")}\n              </>\n            ) : (\n              <>\n                {t(\"I did it\")} <span className=\"rounded-full bg-honey px-1.5 py-px text-[0.6875rem] font-bold text-on-honey\">+{TRIED_POINTS}</span>\n              </>\n            )}\n          </button>\n          {spec.challengeDays && <ChallengeButton item={item} days={spec.challengeDays} t={t} />}\n          {spec.tool === \"pelvic-floor\" && !spec.challengeDays && (\n            <Link\n              href={contentHref(TIMER_ID)}\n              className=\"flex shrink-0 items-center justify-center gap-1.5 rounded-full px-4 py-2.5 text-sm font-bold text-forest ring-1 ring-line\"\n            >\n              <Timer size={16} /> {t(\"Timer\")}\n            </Link>\n          )}\n        </div>\n      </div>\n      <ShareSheet open={sharing} onClose={() => setSharing(false)} item={item} spec={spec} t={t} />\n    </article>\n  );\n}\n\nfunction IconButton({ label, pressed, onClick, children }: { label: string; pressed?: boolean; onClick: () => void; children: React.ReactNode }) {\n  return (\n    <button\n      type=\"button\"\n      aria-label={label}\n      aria-pressed={pressed}\n      onClick={onClick}\n      className=\"flex h-10 w-10 items-center justify-center rounded-full text-ink transition-transform active:scale-90\"\n    >\n      {children}\n    </button>\n  );\n}\n\n/* ───────────── Carousel ───────────── */\n\nfunction Carousel({ children, label, t, onSwipe }: { children: React.ReactNode[]; label: string; t: T; onSwipe?: () => void }) {\n  const ref = useRef<HTMLDivElement>(null);\n  const [index, setIndex] = useState(0);\n  const swiped = useRef(false);\n  const count = children.length;\n\n  const onScroll = useCallback(() => {\n    const el = ref.current;\n    if (!el) return;\n    const i = Math.round(el.scrollLeft / el.clientWidth);\n    setIndex(i);\n    // The first time he swipes into the steps, it counts as using the card (Step 71: reading vs reels)\n    if (i > 0 && !swiped.current) {\n      swiped.current = true;\n      onSwipe?.();\n    }\n  }, [onSwipe]);\n  const go = (i: number) => {\n    const el = ref.current;\n    if (el) el.scrollTo({ left: Math.max(0, Math.min(count - 1, i)) * el.clientWidth, behavior: \"smooth\" });\n  };\n\n  return (\n    <div className=\"group relative\" role=\"region\" aria-roledescription=\"carousel\" aria-label={label}>\n      {/* overflow-x-auto also tells the tab pager to leave this swipe alone */}\n      <div ref={ref} onScroll={onScroll} className=\"no-scrollbar flex snap-x snap-mandatory overflow-x-auto overscroll-x-contain\">\n        {children.map((s, i) => (\n          <div key={i} className=\"aspect-[5/4] w-full shrink-0 snap-center\" aria-roledescription=\"slide\" aria-label={`${i + 1} / ${count}`} aria-hidden={i !== index}>\n            {s}\n          </div>\n        ))}\n      </div>\n      <span className=\"pointer-events-none absolute right-2.5 top-2.5 rounded-full bg-black/45 px-2 py-0.5 text-[0.6875rem] font-bold tabular-nums text-white backdrop-blur\">\n        {index + 1}/{count}\n      </span>\n      {/* Arrows for mouse users on a computer */}\n      <button\n        onClick={() => go(index - 1)}\n        aria-label={t(\"Previous\")}\n        className={`absolute left-2 top-1/2 hidden h-9 w-9 -translate-y-1/2 items-center justify-center rounded-full bg-white/90 text-ink shadow transition-opacity lg:flex ${index === 0 ? \"pointer-events-none opacity-0\" : \"opacity-0 group-hover:opacity-100\"}`}\n      >\n        <ChevronLeft size={18} />\n      </button>\n      <button\n        onClick={() => go(index + 1)}\n        aria-label={t(\"Next\")}\n        className={`absolute right-2 top-1/2 hidden h-9 w-9 -translate-y-1/2 items-center justify-center rounded-full bg-white/90 text-ink shadow transition-opacity lg:flex ${index === count - 1 ? \"pointer-events-none opacity-0\" : \"opacity-0 group-hover:opacity-100\"}`}\n      >\n        <ChevronRight size={18} />\n      </button>\n      <div className=\"flex justify-center gap-1.5 pt-2\" aria-hidden>\n        {children.map((_, i) => (\n          <span key={i} className={`h-1.5 rounded-full transition-all ${i === index ? \"w-4 bg-forest\" : \"w-1.5 bg-line\"}`} />\n        ))}\n      </div>\n    </div>\n  );\n}\n\n/* ───────────── Slides ───────────── */\n\nfunction HookSlide({ item, spec, title, hook, first, t }: { item: ContentItem; spec: ActionSpec; title: string; hook: string; first: boolean; t: T }) {\n  const steps = spec.steps.length;\n  // Step 90: with Save data on, the card opens on its words over a drawn background, not a photo\n  const lite = useSaveData();\n  return (\n    <div className=\"relative h-full w-full overflow-hidden\">\n      <Cover item={lite ? { ...item, coverImageUrl: undefined } : item} className=\"absolute inset-0 h-full w-full\" showPlay={false} />\n      <div className=\"absolute inset-0 bg-gradient-to-t from-black/85 via-black/45 to-black/5\" />\n      <div className=\"absolute inset-x-0 bottom-0 px-4 pb-3.5 text-white\">\n        <h3 className=\"line-clamp-3 font-display text-[1.4375rem] font-bold leading-[1.1]\">{title}</h3>\n        <p className=\"mt-1.5 line-clamp-2 text-[0.875rem] leading-snug text-white/85\">{hook}</p>\n        <p className=\"mt-2.5 flex items-center gap-1.5 text-[0.8125rem] font-semibold text-white\">\n          <span className=\"inline-flex w-5 shrink-0 justify-center\">\n            <Hand size={15} className={first ? \"swipe-hand\" : \"\"} aria-hidden />\n          </span>\n          {t(steps === 1 ? \"Swipe for the step\" : \"Swipe for {n} steps\", { n: steps })}\n        </p>\n      </div>\n    </div>\n  );\n}\n\nfunction MediaSlide({ item, t }: { item: ContentItem; t: T }) {\n  const yt = youtubeId(item.videoUrl);\n  if (yt) return <YouTubeFrame id={yt} controls title={item.title} onEnded={() => trackContent(item.id, \"complete\")} className=\"h-full w-full\" />;\n  if (item.videoUrl) {\n    return (\n      <video\n        src={item.videoUrl}\n        poster={item.coverImageUrl ? sized(item.coverImageUrl, 720) : undefined}\n        controls\n        playsInline\n        preload=\"metadata\"\n        onEnded={() => trackContent(item.id, \"complete\")}\n        // Step 92: the whole video, in its own shape (wide or upright), never zoomed in\n        className=\"h-full w-full bg-black object-contain\"\n      />\n    );\n  }\n  return (\n    <div className=\"relative h-full w-full overflow-hidden\">\n      <Cover item={item} className=\"absolute inset-0 h-full w-full\" showPlay={false} />\n      <div className=\"absolute inset-0 bg-black/55\" />\n      <div className=\"absolute inset-x-0 bottom-0 px-4 pb-4\">\n        <p className=\"mb-2 text-[0.6875rem] font-bold uppercase tracking-wider text-mint-strong\">{t(\"Listen\")}</p>\n        <audio src={item.audioUrl} controls preload=\"metadata\" onEnded={() => trackContent(item.id, \"complete\")} className=\"w-full\" />\n      </div>\n    </div>\n  );\n}\n\n/** A text slide: the words sit in the middle, and long text scrolls instead of being cut off. */\nfunction Frame({ className, children }: { className: string; children: React.ReactNode }) {\n  return (\n    <div className={`relative flex h-full w-full flex-col overflow-y-auto overflow-x-hidden px-5 py-4 ${className}`}>\n      <div className=\"relative my-auto\">{children}</div>\n    </div>\n  );\n}\n\nfunction NeedSlide({ need, t }: { need: string[]; t: T }) {\n  return (\n    <Frame className=\"bg-mint text-forest-deep\">\n      <p className=\"text-[0.6875rem] font-bold uppercase tracking-wider text-forest\">{t(\"You need\")}</p>\n      <ul className={`mt-3 ${need.length > 4 ? \"space-y-1.5\" : \"space-y-2.5\"}`}>\n        {need.map((n, i) => (\n          <li key={i} className={`flex items-start gap-2.5 font-semibold leading-snug ${need.length > 4 ? \"text-[0.875rem]\" : \"text-[1rem]\"}`}>\n            <span className=\"mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-forest text-white\">\n              <Check size={12} />\n            </span>\n            {n}\n          </li>\n        ))}\n      </ul>\n    </Frame>\n  );\n}\n\nfunction StepSlide({ n, total, title, text, t }: { n: number; total: number; title?: string; text: string; t: T }) {\n  const long = text.length > 120;\n  return (\n    <div className=\"relative h-full w-full overflow-hidden bg-forest-deep text-white\">\n      <span className=\"pointer-events-none absolute -right-3 -top-8 font-display text-[10rem] font-bold leading-none text-white/[0.07]\" aria-hidden>\n        {n}\n      </span>\n      <Frame className=\"\">\n        <p className=\"text-[0.6875rem] font-bold uppercase tracking-wider text-mint-strong\">{t(\"Step {n} of {total}\", { n, total })}</p>\n        {title && <p className=\"mt-2 font-display text-[1.3125rem] font-bold leading-tight\">{title}</p>}\n        <p className={`${title ? `mt-1.5 ${long ? \"text-[0.9375rem]\" : \"text-[1rem]\"}` : `mt-2 font-semibold ${long ? \"text-[1rem]\" : \"text-[1.1875rem]\"}`} leading-snug text-white/95`}>{text}</p>\n      </Frame>\n    </div>\n  );\n}\n\nfunction WhySlide({ why, t }: { why: string; t: T }) {\n  return (\n    <Frame className=\"bg-surface\">\n      <p className=\"text-[0.6875rem] font-bold uppercase tracking-wider text-forest\">{t(\"The secret\")}</p>\n      <p className={`mt-2 font-display font-bold leading-snug text-ink ${why.length > 110 ? \"text-[1.0625rem]\" : \"text-[1.1875rem]\"}`}>{why}</p>\n      <p className=\"mt-3 text-[0.8125rem] text-ink-soft\">{t(\"Tried it? Tap \\\"I did it\\\" below.\")}</p>\n    </Frame>\n  );\n}\n","src/components/course/LessonPage.tsx":"\"use client\";\n\n// One course lesson (Step 48): audio player, video, or reading.\n// - Continues from where he stopped (on any of his phones).\n// - Counts only what he actually listens to: when he has heard the pass share (70%), the lesson is\n//   finished, points are added and the next lesson opens.\n// - Lock screen shows only \"Lesson 5 · Men's Social\", never the lesson title.\n// - Step 49: audio plays in the app-wide player (keeps playing on other pages, mini player), a 10-second\n//   countdown to the next lesson at the top right when it ends, and lessons that wait for him show what to do.\n\nimport ShapedVideo from \"@/components/media/ShapedVideo\";\nimport { haptic } from \"@/lib/motion/haptics\";\nimport { useCallback, useEffect, useRef, useState } from \"react\";\nimport Link from \"next/link\";\nimport { useSearchParams } from \"next/navigation\";\nimport { AlertTriangle, ArrowLeft, ArrowRight, Check, ListChecks, ListOrdered, Lock, Pause, Play, RotateCcw, RotateCw, ShieldCheck } from \"lucide-react\";\nimport CourseArt from \"./CourseArt\";\nimport Countdown from \"./Countdown\";\nimport { toPlayerLesson } from \"./CoursePlayerHost\";\nimport { LessonDownloadButton } from \"@/components/offline/SaveButtons\";\nimport { coursePlayer, useCoursePlayer } from \"@/lib/course/player\";\nimport { useToast } from \"@/components/motion/Toast\";\nimport { feedStore, useFeed } from \"@/lib/feed/store\";\nimport { pick, useMainCourse } from \"@/lib/course/useCourses\";\nimport { clock, courseView, heardStep, passReached, passSeconds } from \"@/lib/course/progress\";\nimport { lessonAfter, lessonMinutes, type Course, type FlatLesson } from \"@/lib/course/types\";\nimport { useT } from \"@/lib/i18n\";\nimport { useMediaSrc } from \"@/lib/course/media\";\n\nconst SPEEDS = [1, 1.25, 1.5, 0.75];\n\nexport default function LessonPage({ id }: { id: string }) {\n  const { course, ready } = useMainCourse();\n  const feed = useFeed();\n  const t = useT();\n  const sw = t.lang === \"sw\";\n\n  const back = (\n    <Link href=\"/man/course\" className=\"flex items-center gap-1 text-sm text-ink-soft\">\n      <ArrowLeft size={16} /> {t(\"Course\")}\n    </Link>\n  );\n\n  if (!course || !feed.ready) {\n    return (\n      <div className=\"space-y-4\">\n        {back}\n        {ready && !course ? (\n          <div className=\"rounded-3xl bg-surface p-8 text-center ring-1 ring-line\">\n            <p className=\"font-semibold\">{t(\"This lesson isn't available\")}</p>\n          </div>\n        ) : (\n          <div className=\"h-72 animate-pulse rounded-[28px] bg-forest-deep/15\" />\n        )}\n      </div>\n    );\n  }\n\n  const v = courseView(course, feed.course);\n  const i = v.lessons.findIndex((l) => l.id === id);\n  const lesson = v.lessons[i];\n  if (!lesson) {\n    return (\n      <div className=\"space-y-4\">\n        {back}\n        <div className=\"rounded-3xl bg-surface p-8 text-center ring-1 ring-line\">\n          <p className=\"font-semibold\">{t(\"This lesson isn't available\")}</p>\n          <p className=\"mt-1 text-sm text-ink-soft\">{t(\"It may have been moved or removed.\")}</p>\n        </div>\n      </div>\n    );\n  }\n  if (lesson.state === \"locked\" || lesson.state === \"soon\") {\n    return (\n      <div className=\"space-y-4\">\n        {back}\n        <div className=\"rounded-3xl bg-surface p-8 text-center ring-1 ring-line\">\n          <Lock className=\"mx-auto text-ink-soft\" size={26} />\n          <p className=\"mt-2 font-semibold\">{lesson.state === \"soon\" ? t(\"Coming soon\") : t(\"This lesson opens soon\")}</p>\n          <p className=\"mt-1 text-sm text-ink-soft\">\n            {lesson.state === \"soon\" ? t(\"We're still adding this lesson.\") : t(\"Finish the lessons before it, one after another.\")}\n          </p>\n          {v.current && (\n            <Link href={`/man/course/${v.current.id}`} className=\"mt-4 inline-block rounded-full bg-forest px-5 py-2.5 text-sm font-semibold text-white\">\n              {t(\"Go to lesson {n}\", { n: v.current.number })}\n            </Link>\n          )}\n        </div>\n      </div>\n    );\n  }\n\n  const mod = course.modules[lesson.moduleIndex];\n  const nextLesson = v.lessons.slice(i + 1).find((l) => l.state !== \"soon\") ?? null;\n  const done = lesson.state === \"done\";\n  const caution = pick(sw, lesson.caution, lesson.cautionSw);\n  const summary = pick(sw, lesson.summary, lesson.summarySw);\n  const points = (sw ? lesson.keyPointsSw : lesson.keyPoints) ?? lesson.keyPoints ?? lesson.keyPointsSw;\n\n  return (\n    <article className=\"stagger space-y-5\" key={lesson.id}>\n      <div className=\"flex items-center justify-between\">\n        {back}\n        <span className=\"text-xs font-semibold text-ink-soft\">\n          {t(\"Lesson {n} of {total}\", { n: lesson.number, total: v.lessons.filter((l) => l.state !== \"soon\").length })}\n        </span>\n      </div>\n\n      {lesson.kind === \"reading\" ? (\n        <header className=\"rounded-[28px] bg-forest-deep p-5 text-white\">\n          <p className=\"text-[0.6875rem] font-semibold uppercase tracking-wider text-mint-strong\">\n            {t(\"Module {n}\", { n: lesson.moduleIndex + 1 })} · {pick(sw, mod.title, mod.titleSw)}\n          </p>\n          <h1 className=\"mt-2 text-[1.5rem] font-bold leading-tight\">{pick(sw, lesson.title, lesson.titleSw)}</h1>\n          <p className=\"mt-1 text-xs text-mint\">{t(\"Reading\")} · {t(\"{n} min\", { n: lessonMinutes(lesson) })}</p>\n        </header>\n      ) : (\n        lesson.kind === \"audio\" ? (\n          <AudioPlayer course={course} lesson={lesson} moduleTitle={pick(sw, mod.title, mod.titleSw)} done={done} />\n        ) : (\n          <Player course={course} lesson={lesson} moduleTitle={pick(sw, mod.title, mod.titleSw)} done={done} hasNext={Boolean(nextLesson)} />\n        )\n      )}\n\n      {lesson.kind !== \"reading\" && <LessonDownloadButton lesson={lesson} />}\n\n      {caution && (\n        <p className=\"flex items-start gap-2 rounded-2xl bg-amber-50 p-4 text-sm text-amber-900 ring-1 ring-amber-200 dark:ring-amber-900\">\n          <AlertTriangle size={16} className=\"mt-0.5 shrink-0\" />\n          <span>{caution}</span>\n        </p>\n      )}\n\n      {summary && <p className=\"px-1 text-[0.9375rem] leading-relaxed text-ink-soft\">{summary}</p>}\n\n      {lesson.kind === \"reading\" && <Reading lesson={lesson} done={done} hasNext={Boolean(nextLesson)} />}\n\n      {points && points.length > 0 && (\n        <div className=\"rounded-3xl bg-surface p-5 ring-1 ring-line\">\n          <h2 className=\"font-bold\">{t(\"Key points\")}</h2>\n          <ol className=\"mt-3 space-y-2\">\n            {points.map((k, n) => (\n              <li key={n} className=\"flex gap-3 text-sm\">\n                <span className=\"flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-mint text-xs font-bold text-forest\">{n + 1}</span>\n                {k}\n              </li>\n            ))}\n          </ol>\n        </div>\n      )}\n\n      {/* Lessons that wait for him: what to do before moving on */}\n      {(() => {\n        const after = lessonAfter(lesson);\n        const task = pick(sw, after.task, after.taskSw);\n        return after.mode === \"wait\" && task && nextLesson ? (\n          <p className=\"flex items-start gap-2 rounded-2xl bg-mint/60 p-4 text-sm text-forest-deep\">\n            <ListChecks size={16} className=\"mt-0.5 shrink-0\" />\n            <span>\n              <b className=\"font-semibold\">{t(\"Before the next lesson\")}:</b> {task}\n            </span>\n          </p>\n        ) : null;\n      })()}\n\n      {done && nextLesson ? (\n        <Link\n          href={`/man/course/${nextLesson.id}${nextLesson.kind === \"reading\" ? \"\" : \"?play=1\"}`}\n          className=\"flex w-full items-center gap-3 rounded-3xl bg-forest p-4 text-white transition-transform active:scale-[0.99]\"\n        >\n          <span className=\"flex h-11 w-11 shrink-0 items-center justify-center rounded-full bg-white/15\">\n            <ArrowRight size={18} />\n          </span>\n          <span className=\"min-w-0 flex-1\">\n            <span className=\"block text-[0.6875rem] font-semibold text-mint-strong\">{t(\"Next lesson\")} · {nextLesson.number}</span>\n            <span className=\"block truncate text-sm font-semibold\">{pick(sw, nextLesson.title, nextLesson.titleSw)}</span>\n          </span>\n        </Link>\n      ) : done && !nextLesson && v.finished ? (\n        <div className=\"rounded-3xl bg-mint p-5 text-center\">\n          <p className=\"text-lg font-bold text-forest-deep\">{t(\"Course complete. Well done!\")}</p>\n          <p className=\"mt-1 text-sm text-forest\">{t(\"Listen to any lesson again, any time.\")}</p>\n        </div>\n      ) : null}\n\n      <Link href=\"/man/course\" className=\"flex items-center justify-center gap-1.5 rounded-full py-3 text-sm font-semibold text-ink ring-1 ring-line\">\n        <ListOrdered size={16} /> {t(\"All lessons\")}\n      </Link>\n\n      <p className=\"flex items-start gap-1.5 rounded-2xl bg-bg px-3 py-2 text-[0.6875rem] leading-snug text-ink-soft ring-1 ring-line\">\n        <ShieldCheck size={13} className=\"mt-px shrink-0 text-forest\" />\n        <span>{pick(sw, course.credit, course.creditSw)}</span>\n      </p>\n    </article>\n  );\n}\n\n/* ───────────── Audio (app-wide player, Step 49) ───────────── */\n\nfunction AudioPlayer({ course, lesson, moduleTitle, done }: { course: Course; lesson: FlatLesson & { state: string; progress?: { pos: number; heard: number } }; moduleTitle: string; done: boolean }) {\n  const t = useT();\n  const sw = t.lang === \"sw\";\n  const params = useSearchParams();\n  const p = useCoursePlayer();\n  const mine = p.lesson?.id === lesson.id;\n  const load = useCallback(\n    (autoplay: boolean) => coursePlayer.load(toPlayerLesson(course, lesson, sw), lesson.progress ?? {}, { autoplay, lockLabel: t(\"Lesson {n}\", { n: \"{n}\" }) }),\n    [course, lesson, sw, t],\n  );\n\n  // \"Play\" on the course card brings him here with ?play=1: start straight away\n  useEffect(() => {\n    if (params.get(\"play\") === \"1\" && coursePlayer.get().lesson?.id !== lesson.id) load(true);\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [lesson.id]);\n\n  const time = mine ? p.time : lesson.progress?.pos ?? 0;\n  const duration = (mine && p.duration) || lesson.seconds || 0;\n  const heard = mine ? p.heard : lesson.progress?.heard ?? 0;\n  const playing = mine && p.playing;\n  const finished = done || (mine && Boolean(p.lesson?.done));\n  const need = passSeconds(duration, course.passPercent);\n  const heardPct = duration ? Math.min(100, Math.round((heard / duration) * 100)) : 0;\n  const SPEED_LIST = SPEEDS;\n\n  return (\n    <section className=\"relative overflow-hidden rounded-[28px] bg-forest-deep text-white\">\n      {/* \"Next lesson in 10\" when it ends */}\n      <Countdown forLesson={lesson.id} className=\"absolute right-3 top-3 z-10\" />\n      <div className=\"flex justify-center pt-7\">\n        <CourseArt className={`h-28 w-28 rounded-[28px] shadow-lg transition-transform duration-500 ${playing ? \"scale-105\" : \"\"}`} size={40} />\n      </div>\n      <div className=\"px-5 pb-5 pt-5 text-center\">\n        <p className=\"text-[0.6875rem] font-semibold uppercase tracking-wider text-mint-strong\">\n          {t(\"Module {n}\", { n: lesson.moduleIndex + 1 })} · {moduleTitle}\n        </p>\n        <h1 className=\"mt-1.5 text-[1.5rem] font-bold leading-tight\">{pick(sw, lesson.title, lesson.titleSw)}</h1>\n        {!sw && <p className=\"mt-1 text-xs text-mint\">{t(\"In Kiswahili\")}</p>}\n\n        <input\n          type=\"range\"\n          min={0}\n          max={Math.max(duration, 1)}\n          step={1}\n          value={Math.min(time, duration || time)}\n          disabled={!mine}\n          onChange={(e) => coursePlayer.seek(Number(e.target.value))}\n          aria-label={t(\"Position in the lesson\")}\n          className=\"course-range mt-5 w-full disabled:opacity-60\"\n          style={{ [\"--pct\" as string]: `${duration ? (time / duration) * 100 : 0}%` }}\n        />\n        <div className=\"mt-1 flex justify-between text-left text-[0.6875rem] tabular-nums text-mint\">\n          <span>{clock(time)}</span>\n          <span>-{clock(Math.max(0, duration - time))}</span>\n        </div>\n        <div className=\"mt-3 flex items-center justify-between\">\n          <button\n            onClick={() => coursePlayer.setSpeed(SPEED_LIST[(SPEED_LIST.indexOf(p.speed) + 1) % SPEED_LIST.length])}\n            className=\"flex h-10 w-14 items-center justify-center rounded-full bg-white/10 text-xs font-bold tabular-nums\"\n            aria-label={t(\"Playback speed\")}\n          >\n            {p.speed}×\n          </button>\n          <button onClick={() => mine && coursePlayer.skip(-15)} disabled={!mine} className=\"relative flex h-12 w-12 items-center justify-center rounded-full text-white disabled:opacity-40\" aria-label={t(\"Back 15 seconds\")}>\n            <RotateCcw size={26} />\n            <span className=\"absolute text-[0.5625rem] font-bold\">15</span>\n          </button>\n          <button\n            onClick={() => (mine ? coursePlayer.toggle() : load(true))}\n            className=\"flex h-16 w-16 items-center justify-center rounded-full bg-mint-strong text-forest-deep shadow-lg transition-transform active:scale-95\"\n            aria-label={playing ? t(\"Pause\") : t(\"Play\")}\n          >\n            {playing ? <Pause size={26} fill=\"currentColor\" /> : <Play size={26} fill=\"currentColor\" className=\"translate-x-0.5\" />}\n          </button>\n          <button onClick={() => mine && coursePlayer.skip(15)} disabled={!mine} className=\"relative flex h-12 w-12 items-center justify-center rounded-full text-white disabled:opacity-40\" aria-label={t(\"Forward 15 seconds\")}>\n            <RotateCw size={26} />\n            <span className=\"absolute text-[0.5625rem] font-bold\">15</span>\n          </button>\n          <span className=\"w-14\" />\n        </div>\n\n        {mine && p.failed && <p className=\"mt-3 rounded-2xl bg-white/10 p-3 text-left text-xs text-mint\">{t(\"This lesson couldn't play. Check your internet and try again.\")}</p>}\n\n        <div className=\"mt-4 flex items-center gap-2 rounded-2xl bg-white/10 px-3 py-2.5 text-left text-xs text-mint\">\n          {finished ? (\n            <>\n              <Check size={15} className=\"shrink-0 text-mint-strong\" /> {t(\"Lesson finished · +{n} points\", { n: lesson.points })}\n            </>\n          ) : (\n            <span className=\"min-w-0 flex-1\">\n              <span className=\"block\">{t(\"{n}% heard · the next lesson opens at {pass}%\", { n: heardPct, pass: course.passPercent })}</span>\n              <span className=\"relative mt-2 block h-1.5 overflow-hidden rounded-full bg-white/15\">\n                <span className=\"absolute inset-y-0 left-0 rounded-full bg-mint-strong\" style={{ width: `${Math.min(100, (heard / Math.max(need, 1)) * 100)}%` }} />\n              </span>\n            </span>\n          )}\n        </div>\n        <p className=\"mt-2 text-[0.6875rem] text-mint/80\">{t(\"Keeps playing when you leave this page.\")}</p>\n      </div>\n    </section>\n  );\n}\n\n/* ───────────── Video ───────────── */\n\nfunction Player({ course, lesson, moduleTitle, done, hasNext }: { course: Course; lesson: FlatLesson & { progress?: { pos: number; heard: number } }; moduleTitle: string; done: boolean; hasNext: boolean }) {\n  const t = useT();\n  const sw = t.lang === \"sw\";\n  const showToast = useToast();\n  const params = useSearchParams();\n  const audio = useRef<HTMLAudioElement>(null);\n  const video = useRef<HTMLVideoElement>(null);\n  const media = useCallback(() => (lesson.kind === \"video\" ? video.current : audio.current), [lesson.kind]);\n\n  const [playing, setPlaying] = useState(false);\n  const [time, setTime] = useState(lesson.progress?.pos ?? 0);\n  const [duration, setDuration] = useState(lesson.seconds ?? 0);\n  const [speed, setSpeed] = useState(1);\n  const [heard, setHeard] = useState(lesson.progress?.heard ?? 0);\n  const [failed, setFailed] = useState(false);\n\n  // Kept in refs so the event handlers always see the latest values\n  const heardRef = useRef(lesson.progress?.heard ?? 0);\n  const prev = useRef(lesson.progress?.pos ?? 0);\n  const lastSave = useRef(0);\n  const doneRef = useRef(done);\n  doneRef.current = done;\n\n  const save = useCallback(() => {\n    const el = media();\n    if (!el) return;\n    feedStore.saveCourseSpot(lesson.id, el.ended ? 0 : el.currentTime, heardRef.current);\n    lastSave.current = Date.now();\n  }, [lesson.id, media]);\n\n  const checkPass = useCallback(\n    (len: number) => {\n      if (doneRef.current || !passReached(heardRef.current, len, course.passPercent)) return;\n      doneRef.current = true;\n      feedStore.saveCourseSpot(lesson.id, media()?.currentTime ?? 0, heardRef.current);\n      feedStore.finishCourseLesson(lesson.id, lesson.points);\n      haptic(\"success\");\n      showToast(hasNext ? t(\"+{n} points · Next lesson open\", { n: lesson.points }) : t(\"+{n} points\", { n: lesson.points }));\n    },\n    [course.passPercent, hasNext, lesson.id, lesson.points, media, showToast, t],\n  );\n\n  // Start where he stopped; play straight away when he pressed Play on the card\n  const onLoaded = () => {\n    const el = media();\n    if (!el) return;\n    const len = Number.isFinite(el.duration) && el.duration > 0 ? el.duration : lesson.seconds ?? 0;\n    setDuration(len);\n    const pos = lesson.progress?.pos ?? 0;\n    if (pos > 0 && pos < len - 5) el.currentTime = pos;\n    prev.current = el.currentTime;\n    if (params.get(\"play\") === \"1\") el.play().catch(() => {});\n  };\n\n  const onTime = () => {\n    const el = media();\n    if (!el) return;\n    const add = heardStep(prev.current, el.currentTime, el.playbackRate);\n    prev.current = el.currentTime;\n    if (add) {\n      const len = duration || el.duration || 0;\n      heardRef.current = Math.min(heardRef.current + add, len || Infinity);\n      setHeard(heardRef.current);\n      checkPass(len);\n    }\n    setTime(el.currentTime);\n    if (Date.now() - lastSave.current > 5000) save();\n  };\n\n  // Save when he leaves the page or the app goes to the background\n  useEffect(() => {\n    const onHide = () => document.visibilityState === \"hidden\" && save();\n    document.addEventListener(\"visibilitychange\", onHide);\n    return () => {\n      document.removeEventListener(\"visibilitychange\", onHide);\n      save();\n    };\n  }, [save]);\n\n  // Lock screen: discreet title, and the usual buttons\n  useEffect(() => {\n    if (typeof navigator === \"undefined\" || !(\"mediaSession\" in navigator) || typeof MediaMetadata === \"undefined\") return;\n    navigator.mediaSession.metadata = new MediaMetadata({ title: t(\"Lesson {n}\", { n: lesson.number }), artist: \"Men's Social\" });\n    const jump = (s: number) => () => {\n      const el = media();\n      if (el) el.currentTime = Math.max(0, Math.min(el.currentTime + s, el.duration || Infinity));\n    };\n    navigator.mediaSession.setActionHandler(\"play\", () => void media()?.play());\n    navigator.mediaSession.setActionHandler(\"pause\", () => media()?.pause());\n    navigator.mediaSession.setActionHandler(\"seekbackward\", jump(-15));\n    navigator.mediaSession.setActionHandler(\"seekforward\", jump(15));\n    return () => {\n      for (const a of [\"play\", \"pause\", \"seekbackward\", \"seekforward\"] as const) navigator.mediaSession.setActionHandler(a, null);\n    };\n  }, [lesson.number, media, t]);\n\n  const toggle = () => {\n    const el = media();\n    if (!el) return;\n    if (el.paused) el.play().catch(() => setFailed(true));\n    else el.pause();\n  };\n  const skip = (s: number) => {\n    const el = media();\n    if (!el) return;\n    el.currentTime = Math.max(0, Math.min(el.currentTime + s, (el.duration || duration) - 0.5));\n    prev.current = el.currentTime;\n    setTime(el.currentTime);\n  };\n  const cycleSpeed = () => {\n    const next = SPEEDS[(SPEEDS.indexOf(speed) + 1) % SPEEDS.length];\n    setSpeed(next);\n    const el = media();\n    if (el) el.playbackRate = next;\n  };\n\n  const need = passSeconds(duration || lesson.seconds || 0, course.passPercent);\n  const mediaSrc = useMediaSrc(lesson.mediaUrl); // private files: a one-day link (Step 59)\n  const heardPct = duration ? Math.min(100, Math.round((heard / duration) * 100)) : 0;\n  const common = {\n    src: mediaSrc || undefined,\n    preload: \"metadata\" as const,\n    onLoadedMetadata: onLoaded,\n    onTimeUpdate: onTime,\n    onPlay: () => {\n      setPlaying(true);\n      coursePlayer.pause(); // a video lesson takes over from any audio lesson\n    },\n    onPause: () => {\n      setPlaying(false);\n      save();\n    },\n    onEnded: () => {\n      setPlaying(false);\n      save();\n    },\n    onSeeked: () => {\n      prev.current = media()?.currentTime ?? 0;\n    },\n    onError: () => setFailed(true),\n  };\n\n  return (\n    <section className=\"overflow-hidden rounded-[28px] bg-forest-deep text-white\">\n      {lesson.kind === \"video\" ? (\n        <ShapedVideo ref={video} {...common} controls playsInline />\n      ) : (\n        <>\n          <audio ref={audio} {...common} />\n          <div className=\"flex justify-center pt-7\">\n            <CourseArt className={`h-28 w-28 rounded-[28px] shadow-lg transition-transform duration-500 ${playing ? \"scale-105\" : \"\"}`} size={40} />\n          </div>\n        </>\n      )}\n      <div className={`px-5 pb-5 ${lesson.kind === \"video\" ? \"pt-4\" : \"pt-5 text-center\"}`}>\n        <p className=\"text-[0.6875rem] font-semibold uppercase tracking-wider text-mint-strong\">\n          {t(\"Module {n}\", { n: lesson.moduleIndex + 1 })} · {moduleTitle}\n        </p>\n        <h1 className=\"mt-1.5 text-[1.5rem] font-bold leading-tight\">{pick(sw, lesson.title, lesson.titleSw)}</h1>\n        {!sw && <p className=\"mt-1 text-xs text-mint\">{t(\"In Kiswahili\")}</p>}\n\n        {lesson.kind === \"audio\" && (\n          <>\n            <input\n              type=\"range\"\n              min={0}\n              max={Math.max(duration, 1)}\n              step={1}\n              value={Math.min(time, duration || time)}\n              onChange={(e) => {\n                const el = media();\n                if (!el) return;\n                el.currentTime = Number(e.target.value);\n                prev.current = el.currentTime;\n                setTime(el.currentTime);\n              }}\n              aria-label={t(\"Position in the lesson\")}\n              className=\"course-range mt-5 w-full\"\n              style={{ [\"--pct\" as string]: `${duration ? (time / duration) * 100 : 0}%` }}\n            />\n            <div className=\"mt-1 flex justify-between text-left text-[0.6875rem] tabular-nums text-mint\">\n              <span>{clock(time)}</span>\n              <span>-{clock(Math.max(0, duration - time))}</span>\n            </div>\n            <div className=\"mt-3 flex items-center justify-between\">\n              <button onClick={cycleSpeed} className=\"flex h-10 w-14 items-center justify-center rounded-full bg-white/10 text-xs font-bold tabular-nums\" aria-label={t(\"Playback speed\")}>\n                {speed}×\n              </button>\n              <button onClick={() => skip(-15)} className=\"relative flex h-12 w-12 items-center justify-center rounded-full text-white\" aria-label={t(\"Back 15 seconds\")}>\n                <RotateCcw size={26} />\n                <span className=\"absolute text-[0.5625rem] font-bold\">15</span>\n              </button>\n              <button\n                onClick={toggle}\n                className=\"flex h-16 w-16 items-center justify-center rounded-full bg-mint-strong text-forest-deep shadow-lg transition-transform active:scale-95\"\n                aria-label={playing ? t(\"Pause\") : t(\"Play\")}\n              >\n                {playing ? <Pause size={26} fill=\"currentColor\" /> : <Play size={26} fill=\"currentColor\" className=\"translate-x-0.5\" />}\n              </button>\n              <button onClick={() => skip(15)} className=\"relative flex h-12 w-12 items-center justify-center rounded-full text-white\" aria-label={t(\"Forward 15 seconds\")}>\n                <RotateCw size={26} />\n                <span className=\"absolute text-[0.5625rem] font-bold\">15</span>\n              </button>\n              <span className=\"w-14\" />\n            </div>\n          </>\n        )}\n\n        {failed && <p className=\"mt-3 rounded-2xl bg-white/10 p-3 text-left text-xs text-mint\">{t(\"This lesson couldn't play. Check your internet and try again.\")}</p>}\n\n        <div className=\"mt-4 flex items-center gap-2 rounded-2xl bg-white/10 px-3 py-2.5 text-left text-xs text-mint\">\n          {done ? (\n            <>\n              <Check size={15} className=\"shrink-0 text-mint-strong\" /> {t(\"Lesson finished · +{n} points\", { n: lesson.points })}\n            </>\n          ) : (\n            <span className=\"min-w-0 flex-1\">\n              <span className=\"block\">{t(\"{n}% heard · the next lesson opens at {pass}%\", { n: heardPct, pass: course.passPercent })}</span>\n              <span className=\"relative mt-2 block h-1.5 overflow-hidden rounded-full bg-white/15\">\n                <span className=\"absolute inset-y-0 left-0 rounded-full bg-mint-strong\" style={{ width: `${Math.min(100, (heard / Math.max(need, 1)) * 100)}%` }} />\n              </span>\n            </span>\n          )}\n        </div>\n      </div>\n    </section>\n  );\n}\n\n/* ───────────── Reading ───────────── */\n\nfunction Reading({ lesson, done, hasNext }: { lesson: FlatLesson; done: boolean; hasNext: boolean }) {\n  const t = useT();\n  const showToast = useToast();\n  const [lang, setLang] = useState<\"en\" | \"sw\">(t.lang === \"sw\" || !lesson.body?.length ? \"sw\" : \"en\");\n  const body = (lang === \"sw\" ? lesson.bodySw : lesson.body) ?? lesson.bodySw ?? lesson.body ?? [];\n  const both = Boolean(lesson.body?.length && lesson.bodySw?.length);\n  return (\n    <>\n      {both && (\n        <div className=\"inline-flex rounded-full bg-surface p-1 text-xs font-semibold ring-1 ring-line\" role=\"tablist\" aria-label={t(\"Language\")}>\n          {([\"en\", \"sw\"] as const).map((l) => (\n            <button key={l} role=\"tab\" aria-selected={lang === l} onClick={() => setLang(l)} className={`rounded-full px-3 py-1.5 ${lang === l ? \"bg-forest text-white\" : \"text-ink-soft\"}`}>\n              {l === \"en\" ? \"English\" : \"Kiswahili\"}\n            </button>\n          ))}\n        </div>\n      )}\n      <div lang={lang} className=\"space-y-3 rounded-3xl bg-surface p-5 text-[0.9375rem] leading-relaxed ring-1 ring-line\">\n        {body.map((p, i) =>\n          p.startsWith(\"## \") ? (\n            <h2 key={i} className=\"pt-2 text-lg font-bold\">\n              {p.slice(3)}\n            </h2>\n          ) : (\n            <p key={i}>{p}</p>\n          ),\n        )}\n      </div>\n      <button\n        onClick={() => {\n          if (done) return;\n          feedStore.finishCourseLesson(lesson.id, lesson.points);\n          haptic(\"success\");\n      showToast(hasNext ? t(\"+{n} points · Next lesson open\", { n: lesson.points }) : t(\"+{n} points\", { n: lesson.points }));\n        }}\n        className={`flex w-full items-center justify-center gap-2 rounded-full py-3.5 text-sm font-semibold transition-transform active:scale-[0.98] ${done ? \"bg-mint text-forest\" : \"bg-forest text-white\"}`}\n      >\n        {done ? (\n          <>\n            <Check size={16} /> {t(\"You've read this\")}\n          </>\n        ) : (\n          t(\"I've read it · +{n} points\", { n: lesson.points })\n        )}\n      </button>\n    </>\n  );\n}\n","src/components/studio/Editor.tsx":"\"use client\";\n\nimport ShapedVideo from \"@/components/media/ShapedVideo\";\nimport { UPRIGHT, WIDE } from \"@/lib/media/videoShape\";\nimport { CIRCLES, NO_CIRCLE, circlesOf, isCircle, setCircles } from \"@/lib/content/circles\";\nimport { useEffect, useMemo, useRef, useState } from \"react\";\nimport Link from \"next/link\";\nimport { useRouter } from \"next/navigation\";\nimport {\n  AlertTriangle,\n  ArrowLeft,\n  Archive,\n  CheckCircle2,\n  Clock,\n  Copy,\n  Film,\n  History,\n  Mic,\n  ImagePlus,\n  MapPin,\n  Loader2,\n  OctagonX,\n  Plus,\n  Trash2,\n  X,\n} from \"lucide-react\";\nimport Preview from \"./Preview\";\nimport { YouTubeFrame } from \"@/components/media/YouTubeFrame\";\nimport { cleanYouTubeUrl, isYouTubeShort, youtubeId } from \"@/lib/content/youtube\";\nimport { MAX_VIDEO_BYTES } from \"@/lib/content/repo\";\nimport { canShrink, shrinkVideo } from \"@/lib/studio/shrinkVideo\";\nimport { useStudio } from \"@/components/admin/AdminShell\";\nimport type { Version } from \"@/lib/content/repo\";\nimport { Notice } from \"./StudioGate\";\nimport {\n  displayStatus,\n  STATUS_LABEL,\n  STATUS_STYLE,\n} from \"@/lib/admin/contentStatus\";\nimport { Confirm, Drawer, btn } from \"@/components/admin/ui\";\nimport { useToast } from \"@/components/motion/Toast\";\nimport { LIBRARY, TOPICS } from \"@/lib/content/library\";\nimport { getContentRepo } from \"@/lib/content/repo\";\nimport { KIND_LABEL } from \"@/lib/content/select\";\nimport type {\n  ContentItem,\n  ContentKind,\n  ContentStatus,\n  QuizQuestion,\n  ToolId,\n} from \"@/lib/content/types\";\nimport { checkClaims } from \"@/lib/studio/claims\";\nimport { placesOf, presetFor, type PlaceId } from \"@/lib/studio/places\";\nimport type { ChallengeId, TopicId } from \"@/lib/content/types\";\nimport { actionOf } from \"@/lib/content/actions\";\nimport HookFields from \"./HookFields\";\nimport {\n  blankItem,\n  fromLines,\n  fromParagraphs,\n  ID_RULE,\n  publishProblems,\n  slugify,\n  toLines,\n  toParagraphs,\n} from \"@/lib/studio/validate\";\n\nconst KINDS: ContentKind[] = [\n  \"reel\",\n  \"article\",\n  \"guide\",\n  \"expert\",\n  \"video\",\n  \"quiz\",\n  \"tool\",\n  \"audio\",\n  \"infographic\",\n];\nconst TONES: ContentItem[\"cover\"][\"tone\"][] = [\n  \"forest\",\n  \"night\",\n  \"mint\",\n  \"sand\",\n  \"clay\",\n];\nconst MOTIFS: ContentItem[\"cover\"][\"motif\"][] = [\n  \"rings\",\n  \"waves\",\n  \"arc\",\n  \"grid\",\n  \"dots\",\n];\nconst TONE_SWATCH: Record<string, string> = {\n  forest: \"#0f5c46\",\n  night: \"#06261d\",\n  mint: \"#dff3ea\",\n  sand: \"#f1e8d8\",\n  clay: \"#efdcd0\",\n};\nconst TOOLS: { id: ToolId; label: string }[] = [\n  { id: \"pelvic-floor\", label: \"Pelvic floor trainer\" },\n  { id: \"doctor-check\", label: \"Should I see a doctor? check\" },\n];\n\ntype Texts = { body: string; bodySw: string; keyPoints: string; tags: string };\nconst textsOf = (c: ContentItem): Texts => ({\n  body: fromParagraphs(c.body),\n  bodySw: fromParagraphs(c.bodySw),\n  keyPoints: fromLines(c.keyPoints),\n  // Circle tags (\"last\", \"hard\"…) are set with the circle buttons, not typed (Step 80)\n  tags: c.tags.filter((t) => !isCircle(t)).join(\", \"),\n});\n\nconst compose = (draft: ContentItem, texts: Texts): ContentItem => ({\n  ...draft,\n  body: toParagraphs(texts.body),\n  bodySw: toParagraphs(texts.bodySw),\n  keyPoints: toLines(texts.keyPoints),\n  tags: [\n    ...new Set([\n      ...texts.tags\n        .split(\",\")\n        .map((t) => t.trim().toLowerCase())\n        .filter((t) => t && !isCircle(t)),\n      ...draft.tags.filter(isCircle),\n    ]),\n  ],\n});\n\ntype Loaded =\n  | { base: ContentItem; status: ContentStatus | null; copyOfBuiltIn: boolean }\n  | \"missing\";\n\nexport default function Editor({\n  id,\n  preset,\n  copyOf,\n}: {\n  id: string | null;\n  preset?: { place: PlaceId | null; topic: TopicId | null };\n  /** Duplicate: start a new item from this one */\n  copyOf?: string | null;\n}) {\n  const studio = useStudio();\n  const canPublish = studio.can(\"content.publish\");\n  const fresh = () =>\n    presetFor(blankItem(), preset?.place ?? null, preset?.topic ?? null);\n  const router = useRouter();\n  const showToast = useToast();\n  const repo = getContentRepo();\n\n  const [loaded, setLoaded] = useState<Loaded | null>(\n    id || copyOf ? null : { base: fresh(), status: null, copyOfBuiltIn: false },\n  );\n  const [takenIds, setTakenIds] = useState<Set<string>>(\n    new Set(LIBRARY.map((c) => c.id)),\n  );\n  const [loadError, setLoadError] = useState<string | null>(null);\n\n  const [draft, setDraft] = useState<ContentItem>(blankItem());\n  const [texts, setTexts] = useState<Texts>(textsOf(blankItem()));\n  const [savedJson, setSavedJson] = useState(\"\");\n  const [idTouched, setIdTouched] = useState(false);\n  const [busy, setBusy] = useState<string | null>(null);\n  const [error, setError] = useState<string | null>(null);\n  const fileInput = useRef<HTMLInputElement>(null);\n  const videoInput = useRef<HTMLInputElement>(null);\n  const quickVideo = useRef<HTMLInputElement>(null);\n  // Reels get a short form (video, caption, topic). \"More options\" opens the full editor.\n  const [fullForm, setFullForm] = useState(false);\n  const [ytBlocked, setYtBlocked] = useState<string | null>(null);\n  // Big videos are made smaller in the browser before upload (Step 75)\n  const [shrink, setShrink] = useState<{ pct: number; pass: number; mb: number } | null>(null);\n  const shrinkAbort = useRef<AbortController | null>(null);\n  const audioInput = useRef<HTMLInputElement>(null);\n  const [versions, setVersions] = useState<Version[] | null>(null);\n  const [showHistory, setShowHistory] = useState(false);\n  const [confirmDelete, setConfirmDelete] = useState(false);\n\n  // Load: from the database first, otherwise a built-in item to copy\n  useEffect(() => {\n    repo\n      .listAll()\n      .then((all) => {\n        setTakenIds(\n          new Set([...LIBRARY.map((c) => c.id), ...all.map((c) => c.id)]),\n        );\n        const taken = new Set([\n          ...LIBRARY.map((c) => c.id),\n          ...all.map((c) => c.id),\n        ]);\n        if (!id && copyOf) {\n          // Duplicate: same content, new address, saved as a new draft\n          const src =\n            all.find((c) => c.id === copyOf) ??\n            LIBRARY.find((c) => c.id === copyOf);\n          if (!src) return setLoaded(\"missing\");\n          let newId = slugify(src.title + \" copy\");\n          for (let n = 2; taken.has(newId); n++)\n            newId = slugify(src.title + \" copy \" + n);\n          setLoaded({\n            base: {\n              ...src,\n              id: newId,\n              title: src.title + \" (copy)\",\n              status: \"draft\",\n              featured: undefined,\n              publishAt: undefined,\n              reviewNote: undefined,\n              fixture: false,\n              builtIn: false,\n              updatedAt: undefined,\n            },\n            status: null,\n            copyOfBuiltIn: false,\n          });\n          return;\n        }\n        if (!id) return;\n        const mine = all.find((c) => c.id === id);\n        const builtIn = LIBRARY.find((c) => c.id === id);\n        if (mine)\n          setLoaded({\n            base: mine,\n            status: mine.status ?? \"draft\",\n            copyOfBuiltIn: Boolean(builtIn),\n          });\n        else if (builtIn)\n          setLoaded({\n            base: {\n              ...builtIn,\n              fixture: false,\n              builtIn: false,\n              status: \"draft\",\n            },\n            status: null,\n            copyOfBuiltIn: true,\n          });\n        else setLoaded(\"missing\");\n      })\n      .catch((e: Error) => setLoadError(e.message));\n  }, [id, repo, copyOf]);\n\n  useEffect(() => {\n    if (!loaded || loaded === \"missing\") return;\n    setDraft(loaded.base);\n    setTexts(textsOf(loaded.base));\n    // A Kiswahili translation handed over from Admin → AI: filled in, not saved, marked AI-assisted\n    try {\n      const key = `ms_ai_sw:${loaded.base.id}`;\n      const raw = sessionStorage.getItem(key);\n      if (raw) {\n        sessionStorage.removeItem(key);\n        const sw = JSON.parse(raw) as {\n          titleSw?: string;\n          summarySw?: string;\n          bodySw?: string[];\n        };\n        setDraft((d) => ({\n          ...d,\n          titleSw: sw.titleSw || d.titleSw,\n          summarySw: sw.summarySw || d.summarySw,\n          aiGenerated: true,\n        }));\n        if (Array.isArray(sw.bodySw))\n          setTexts((t) => ({ ...t, bodySw: fromParagraphs(sw.bodySw) }));\n        showToast(\"Kiswahili from AI filled in · check it, then save\");\n      }\n    } catch {}\n    setSavedJson(\n      loaded.status\n        ? JSON.stringify(compose(loaded.base, textsOf(loaded.base)))\n        : \"\",\n    );\n  }, [loaded, showToast]);\n\n  // The item as it will be saved\n  const item: ContentItem = useMemo(\n    () => compose(draft, texts),\n    [draft, texts],\n  );\n\n  const status = loaded && loaded !== \"missing\" ? loaded.status : null; // null = not in the database yet\n  const isNew = status === null;\n  const claims = useMemo(() => checkClaims(item), [item]);\n  const problems = useMemo(() => publishProblems(item), [item]);\n  const idTaken =\n    isNew &&\n    !(loaded !== \"missing\" && loaded?.copyOfBuiltIn) &&\n    takenIds.has(item.id);\n  const dirty = JSON.stringify(item) !== savedJson;\n\n  // Warn before leaving with unsaved changes\n  useEffect(() => {\n    if (!dirty) return;\n    const warn = (e: BeforeUnloadEvent) => e.preventDefault();\n    window.addEventListener(\"beforeunload\", warn);\n    return () => window.removeEventListener(\"beforeunload\", warn);\n  }, [dirty]);\n\n  const set = <K extends keyof ContentItem>(key: K, value: ContentItem[K]) =>\n    setDraft((d) => ({ ...d, [key]: value }));\n  const setText = (key: keyof Texts, value: string) =>\n    setTexts((t) => ({ ...t, [key]: value }));\n\n  function setTitle(title: string) {\n    setDraft((d) => ({\n      ...d,\n      title,\n      id: isNew && !idTouched && !loadedCopy() ? slugify(title) : d.id,\n    }));\n  }\n  const loadedCopy = () =>\n    loaded !== null && loaded !== \"missing\" && loaded.copyOfBuiltIn;\n\n  async function save(next: ContentStatus) {\n    setError(null);\n    if (!ID_RULE.test(item.id))\n      return setError(\"Add a title first (it makes the web address).\");\n    if (idTaken)\n      return setError(\n        `The web address \"${item.id}\" is already used. Change it below the title.`,\n      );\n    if ((next === \"published\" || next === \"review\") && problems.length)\n      return setError(\n        next === \"review\"\n          ? \"Not ready for review yet. See the checklist.\"\n          : \"Not ready to publish yet. See the checklist.\",\n      );\n    const scheduled =\n      next === \"published\" &&\n      item.publishAt &&\n      new Date(item.publishAt) > new Date();\n    setBusy(next);\n    try {\n      const saved = await repo.save(item, next);\n      const merged = {\n        ...item,\n        status: saved.status,\n        updatedAt: saved.updatedAt,\n      };\n      setSavedJson(JSON.stringify(merged));\n      setDraft(merged);\n      setLoaded({ base: merged, status: next, copyOfBuiltIn: loadedCopy() });\n      showToast(\n        scheduled\n          ? `Scheduled for ${new Date(item.publishAt!).toLocaleString(\"en-GB\", { day: \"numeric\", month: \"short\", hour: \"2-digit\", minute: \"2-digit\" })}`\n          : next === \"published\"\n            ? status === \"published\"\n              ? \"Live version updated\"\n              : \"Published\"\n            : next === \"review\"\n              ? \"Sent for review\"\n              : next === \"archived\"\n                ? \"Archived\"\n                : \"Draft saved\",\n      );\n      if (isNew)\n        router.replace(`/studio/edit?id=${encodeURIComponent(item.id)}`);\n    } catch (e) {\n      setError((e as Error).message);\n    } finally {\n      setBusy(null);\n    }\n  }\n\n  async function openHistory() {\n    setShowHistory(true);\n    setVersions(null);\n    try {\n      setVersions(await repo.listVersions(item.id));\n    } catch (e) {\n      setShowHistory(false);\n      setError((e as Error).message);\n    }\n  }\n\n  function loadVersion(v: Version) {\n    // Keeps this item's address; you review the old text, then save or publish it again\n    const restored = {\n      ...v.item,\n      id: item.id,\n      status: item.status,\n      updatedAt: item.updatedAt,\n    };\n    setDraft(restored);\n    setTexts(textsOf(restored));\n    setShowHistory(false);\n    showToast(\"Older version loaded · save to keep it\");\n  }\n\n  async function uploadAudio(file: File | undefined) {\n    if (!file) return;\n    if (!ID_RULE.test(item.id))\n      return setError(\"Add a title first, then the audio.\");\n    setError(null);\n    setBusy(\"audio\");\n    try {\n      set(\"audioUrl\", await repo.uploadAudio(file, item.id));\n      showToast(\"Audio added · save to keep it\");\n    } catch (e) {\n      setError((e as Error).message);\n    } finally {\n      setBusy(null);\n      if (audioInput.current) audioInput.current.value = \"\";\n    }\n  }\n\n  async function remove() {\n    setConfirmDelete(false);\n    setBusy(\"delete\");\n    try {\n      await repo.remove(item.id);\n      setSavedJson(JSON.stringify(item));\n      showToast(\"Deleted\");\n      router.push(\"/studio/content\");\n    } catch (e) {\n      setError((e as Error).message);\n      setBusy(null);\n    }\n  }\n\n  async function upload(file: File | undefined) {\n    if (!file) return;\n    if (!ID_RULE.test(item.id))\n      return setError(\"Add a title first, then the photo.\");\n    setError(null);\n    setBusy(\"image\");\n    try {\n      set(\"coverImageUrl\", await repo.uploadImage(file, item.id));\n      showToast(\"Photo added · save to keep it\");\n    } catch (e) {\n      setError((e as Error).message);\n    } finally {\n      setBusy(null);\n      if (fileInput.current) fileInput.current.value = \"\";\n    }\n  }\n\n  async function uploadVideo(file: File | undefined) {\n    if (!file) return;\n    let vid = item.id;\n    if (!ID_RULE.test(vid)) {\n      if (item.kind !== \"reel\")\n        return setError(\"Add a title first, then the video.\");\n      // A reel can start with the video: it gets its own web address\n      vid = `reel-${Date.now().toString(36)}`;\n      setIdTouched(true);\n      set(\"id\", vid);\n    }\n    setError(null);\n    setBusy(\"video\");\n    try {\n      let toSend = file;\n      if (file.size > MAX_VIDEO_BYTES) {\n        const mb = Math.round(file.size / 1048576);\n        if (!canShrink())\n          throw new Error(`This video is ${mb} MB (the limit is 50 MB). Open the Studio in Chrome to make it smaller here, or shrink it in CapCut (Export → 720p).`);\n        const ac = new AbortController();\n        shrinkAbort.current = ac;\n        setShrink({ pct: 0, pass: 1, mb });\n        let last = -1;\n        toSend = await shrinkVideo(file, {\n          signal: ac.signal,\n          onProgress: (f, pass) => {\n            const pct = Math.floor(f * 100) + pass * 1000;\n            if (pct === last) return;\n            last = pct;\n            setShrink({ pct: f, pass, mb });\n          },\n        });\n        setShrink(null);\n        showToast(`Made smaller: ${mb} MB → ${Math.max(1, Math.round(toSend.size / 1048576))} MB · uploading`);\n      }\n      set(\"videoUrl\", await repo.uploadVideo(toSend, vid));\n      showToast(\"Video added · save to keep it\");\n    } catch (e) {\n      setError((e as Error).message);\n    } finally {\n      setShrink(null);\n      shrinkAbort.current = null;\n      setBusy(null);\n      if (videoInput.current) videoInput.current.value = \"\";\n      if (quickVideo.current) quickVideo.current.value = \"\";\n    }\n  }\n\n  if (loadError) return <Notice title=\"Couldn't load\">{loadError}</Notice>;\n  if (loaded === \"missing\")\n    return (\n      <Notice title=\"Not found\">\n        Nothing with the address &ldquo;{id}&rdquo;.{\" \"}\n        <Link href=\"/studio\" className=\"font-semibold text-forest\">\n          Back to content\n        </Link>\n      </Notice>\n    );\n  if (!loaded)\n    return (\n      <div className=\"flex justify-center py-20 text-ink-soft\">\n        <Loader2 className=\"animate-spin\" />\n      </div>\n    );\n\n  const quick = item.kind === \"reel\" && !fullForm;\n  const yt = youtubeId(item.videoUrl);\n  /** A pasted video link: YouTube links are tidied; a reel gets a web address so the caption can come later. */\n  function pasteVideo(raw: string) {\n    const v = raw.trim();\n    const link = youtubeId(v) ? cleanYouTubeUrl(v)! : v;\n    setYtBlocked(null);\n    setDraft((d) => ({\n      ...d,\n      videoUrl: link || undefined,\n      ...(d.kind === \"reel\" && link && !ID_RULE.test(d.id) ? { id: `reel-${Date.now().toString(36)}` } : {}),\n    }));\n    if (item.kind === \"reel\" && link && !ID_RULE.test(item.id)) setIdTouched(true);\n  }\n  const shrinkNote = shrink ? (\n    <div className=\"space-y-2 rounded-2xl bg-mint/30 p-3 text-sm ring-1 ring-forest/20\" role=\"status\">\n      <p className=\"font-semibold\">\n        Making the video smaller… {Math.round(shrink.pct * 100)}%{shrink.pass > 1 ? \" (second try, a bit smaller)\" : \"\"}\n      </p>\n      <div className=\"h-2 overflow-hidden rounded-full bg-line\">\n        <div className=\"h-full bg-forest transition-[width]\" style={{ width: `${shrink.pct * 100}%` }} />\n      </div>\n      <p className=\"text-xs text-ink-soft\">\n        It&apos;s {shrink.mb} MB, over the 50 MB limit, so it&apos;s being made 720p. This takes about as long as the video itself. Keep this page open and on screen.\n      </p>\n      <button type=\"button\" className={btn.small} onClick={() => shrinkAbort.current?.abort()}>\n        <X size={13} /> Stop\n      </button>\n    </div>\n  ) : null;\n  const ytNote = yt ? (\n    ytBlocked === item.videoUrl ? (\n      <p className=\"text-xs font-semibold text-red-700\">\n        YouTube says this video&apos;s owner doesn&apos;t allow it to play in other apps (or it&apos;s private or removed). Men will see &ldquo;This video can&apos;t play here&rdquo;. Use another video.\n      </p>\n    ) : (\n      <p className=\"text-xs text-ink-soft\">\n        YouTube video · plays inside the app{isYouTubeShort(item.videoUrl) ? \" (Short, upright)\" : \"\"}. YouTube may show its logo, and ads if the channel has them.\n      </p>\n    )\n  ) : null;\n  const caption = item.summary || item.title;\n  /** One caption, written once: the first line is the title, the whole thing the caption, same in both languages. */\n  function setCaption(text: string) {\n    const first = text.split(\"\\n\")[0].trim();\n    const title =\n      first.length > 100 ? first.slice(0, 100).replace(/\\s+\\S*$/, \"\") : first;\n    setDraft((d) => ({\n      ...d,\n      title,\n      titleSw: title || undefined,\n      summary: text,\n      summarySw: text || undefined,\n      inManFeed: false,\n      id: isNew && !idTouched && !loadedCopy() ? slugify(title) : d.id,\n    }));\n  }\n\n  const blocks = claims.filter((c) => c.level === \"block\");\n  const warns = claims.filter((c) => c.level === \"warn\");\n\n  return (\n    <div className=\"space-y-5\">\n      <div className=\"flex flex-wrap items-center justify-between gap-3\">\n        <Link\n          href=\"/studio/content\"\n          className=\"flex items-center gap-1 text-sm text-ink-soft\"\n        >\n          <ArrowLeft size={16} /> All content\n        </Link>\n        <div className=\"flex flex-wrap items-center gap-2\">\n          {status && (\n            <>\n              <button type=\"button\" onClick={openHistory} className={btn.small}>\n                <History size={13} /> History\n              </button>\n              <Link\n                href={`/studio/edit?copy=${encodeURIComponent(item.id)}`}\n                className={btn.small}\n              >\n                <Copy size={13} /> Duplicate\n              </Link>\n            </>\n          )}\n          <span\n            className={`rounded-full px-3 py-1 text-xs font-semibold ring-1 ${status ? STATUS_STYLE[displayStatus({ status, publishAt: loaded.base.publishAt })] : \"bg-bg text-ink-soft ring-line\"}`}\n          >\n            {status\n              ? STATUS_LABEL[\n                  displayStatus({ status, publishAt: loaded.base.publishAt })\n                ]\n              : \"Not saved yet\"}\n            {dirty && status ? \" · unsaved changes\" : \"\"}\n          </span>\n        </div>\n      </div>\n      {status === \"review\" && loaded.base.reviewNote && (\n        <p className=\"rounded-2xl bg-amber-50 px-4 py-3 text-sm text-amber-900\">\n          <b>Review note:</b> {loaded.base.reviewNote}\n        </p>\n      )}\n\n      {loaded.copyOfBuiltIn && (\n        <p className=\"rounded-2xl bg-mint/60 px-4 py-3 text-sm text-forest-deep\">\n          {isNew\n            ? \"You're editing a copy of a built-in item. When you publish it, your version replaces the built-in one in the app.\"\n            : \"This is your edited copy of a built-in item. Published = your version shows in the app.\"}\n        </p>\n      )}\n\n      <div className=\"grid gap-6 lg:grid-cols-[minmax(0,1fr)_360px]\">\n        <div className=\"space-y-5\">\n          {quick ? (\n            <Section title=\"New reel\">\n              <div className=\"flex flex-wrap items-center gap-2 text-xs text-ink-soft\">\n                Making something else?\n                {KINDS.filter((k) => k !== \"reel\")\n                  .slice(0, 3)\n                  .map((k) => (\n                    <button\n                      key={k}\n                      type=\"button\"\n                      onClick={() => set(\"kind\", k)}\n                      className=\"font-semibold text-forest underline\"\n                    >\n                      {KIND_LABEL[k]}\n                    </button>\n                  ))}\n                <button\n                  type=\"button\"\n                  onClick={() => setFullForm(true)}\n                  className=\"font-semibold text-forest underline\"\n                >\n                  More…\n                </button>\n              </div>\n\n              {/* 1. The video */}\n              {item.videoUrl ? (\n                <div className=\"flex items-end gap-3\">\n                  {yt ? (\n                    <YouTubeFrame\n                      id={yt}\n                      controls\n                      title={item.title || \"Reel\"}\n                      onBlocked={() => setYtBlocked(item.videoUrl ?? null)}\n                      className=\"aspect-[9/16] w-36 shrink-0 rounded-2xl\"\n                    />\n                  ) : (\n                    <div className=\"w-36 shrink-0\">\n                      <ShapedVideo src={item.videoUrl} fallback={UPRIGHT} maxHeight=\"16rem\" controls playsInline preload=\"metadata\" className=\"rounded-2xl\" />\n                    </div>\n                  )}\n                  <div className=\"space-y-2\">\n                    <button\n                      type=\"button\"\n                      onClick={() => quickVideo.current?.click()}\n                      disabled={busy === \"video\"}\n                      className={btn.small}\n                    >\n                      {busy === \"video\" ? (\n                        <Loader2 size={13} className=\"animate-spin\" />\n                      ) : (\n                        <Film size={13} />\n                      )}{\" \"}\n                      Change video\n                    </button>\n                  </div>\n                </div>\n              ) : (\n                <button\n                  type=\"button\"\n                  onClick={() => quickVideo.current?.click()}\n                  disabled={busy === \"video\"}\n                  className=\"flex w-full flex-col items-center justify-center gap-2 rounded-3xl border-2 border-dashed border-forest/40 bg-mint/20 py-10 text-forest disabled:opacity-60\"\n                >\n                  {busy === \"video\" ? (\n                    <Loader2 size={28} className=\"animate-spin\" />\n                  ) : (\n                    <Film size={28} />\n                  )}\n                  <span className=\"font-bold\">\n                    {busy === \"video\" ? (shrink ? \"Making it smaller…\" : \"Uploading…\") : \"Choose the video\"}\n                  </span>\n                  <span className=\"text-xs text-ink-soft\">\n                    Upright. Big videos are made smaller for you.\n                  </span>\n                </button>\n              )}\n              <input\n                ref={quickVideo}\n                type=\"file\"\n                accept=\"video/mp4,video/webm,video/quicktime\"\n                className=\"hidden\"\n                onChange={(e) => uploadVideo(e.target.files?.[0])}\n              />\n              <Field label=\"Or paste a YouTube link\" hint=\"A Short or any YouTube video. It plays inside the app, no upload needed.\">\n                <input\n                  className={input}\n                  type=\"url\"\n                  inputMode=\"url\"\n                  placeholder=\"https://youtube.com/shorts/…\"\n                  value={item.videoUrl && !item.videoUrl.includes(\"supabase.co\") ? item.videoUrl : \"\"}\n                  onChange={(e) => pasteVideo(e.target.value)}\n                />\n              </Field>\n              {shrinkNote}\n              {ytNote}\n\n              {/* 2. The caption */}\n              <Field\n                label=\"Caption\"\n                hint=\"Write it once, in Kiswahili or English, or paste the Instagram caption (up to 2,200 characters). The first line is the title; lists with • or ✅ show as tidy points.\"\n              >\n                <textarea\n                  className={`${input} min-h-24`}\n                  value={caption}\n                  onChange={(e) => setCaption(e.target.value)}\n                  placeholder=\"e.g. Mchanganyiko wa vitunguu saumu, tangawizi na manjano\"\n                  maxLength={2200}\n                />\n              </Field>\n\n              {/* 3. Where men find it: the same circles they tap at the top of Discover (Step 80) */}\n              <Field group label=\"Circle on Discover\" hint=\"The circles men tap at the top of Discover. Pick one or more.\">\n                <CirclePicker item={item} onChange={(c, noTopic) => setDraft((d) => setCircles(d, c, noTopic))} />\n              </Field>\n\n              {(problems.length > 0 || blocks.length > 0) &&\n                (item.videoUrl || caption) && (\n                  <ul className=\"space-y-1 rounded-2xl bg-amber-50 px-4 py-3 text-xs text-amber-900\">\n                    {problems.map((p) => (\n                      <li key={p}>• {p}</li>\n                    ))}\n                  </ul>\n                )}\n              <button\n                type=\"button\"\n                onClick={() => setFullForm(true)}\n                className=\"text-xs font-semibold text-ink-soft underline\"\n              >\n                More options (cover photo, schedule, separate Kiswahili text…)\n              </button>\n            </Section>\n          ) : (\n            <>\n              {/* Basics */}\n              <Section title=\"What is it?\">\n                <div className=\"flex flex-wrap gap-2\">\n                  {KINDS.map((k) => (\n                    <Chip\n                      key={k}\n                      on={item.kind === k}\n                      onClick={() => set(\"kind\", k)}\n                    >\n                      {KIND_LABEL[k]}\n                    </Chip>\n                  ))}\n                </div>\n                <Field group label=\"Circle on Discover\" hint=\"The circles men tap at the top of Discover. Pick one or more.\">\n                  <CirclePicker item={item} onChange={(c, noTopic) => setDraft((d) => setCircles(d, c, noTopic))} />\n                </Field>\n              </Section>\n\n              <Section title=\"Title and summary\">\n                <Field label=\"Title (English)\">\n                  <input\n                    className={input}\n                    value={item.title}\n                    onChange={(e) => setTitle(e.target.value)}\n                    placeholder=\"e.g. Why sleep matters for erections\"\n                    maxLength={160}\n                  />\n                </Field>\n                <Field\n                  label=\"Web address\"\n                  hint={\n                    isNew && !loaded.copyOfBuiltIn\n                      ? \"Made from the title. Can't change after the first save.\"\n                      : \"Fixed after the first save.\"\n                  }\n                >\n                  <input\n                    className={`${input} font-mono text-xs`}\n                    value={item.id}\n                    disabled={!isNew || loaded.copyOfBuiltIn}\n                    onChange={(e) => {\n                      setIdTouched(true);\n                      set(\n                        \"id\",\n                        e.target.value\n                          .toLowerCase()\n                          .replace(/[^a-z0-9-]/g, \"-\"),\n                      );\n                    }}\n                  />\n                  {idTaken && (\n                    <p className=\"mt-1 text-xs text-red-700\">\n                      Already used. Change it a little, e.g. add\n                      &ldquo;-2&rdquo;.\n                    </p>\n                  )}\n                </Field>\n                <Field\n                  label=\"Title (Kiswahili)\"\n                  hint=\"Optional, but needed if you add Kiswahili text.\"\n                >\n                  <input\n                    className={input}\n                    value={item.titleSw ?? \"\"}\n                    onChange={(e) =>\n                      set(\"titleSw\", e.target.value || undefined)\n                    }\n                    maxLength={160}\n                  />\n                </Field>\n                <Field\n                  label=\"Summary\"\n                  hint=\"What he gains from it, in one or two short sentences.\"\n                >\n                  <textarea\n                    className={`${input} min-h-20`}\n                    value={item.summary}\n                    onChange={(e) => set(\"summary\", e.target.value)}\n                  />\n                </Field>\n                <Field\n                  label=\"Summary (Kiswahili)\"\n                  hint=\"Optional. Shown when a man uses the app in Kiswahili.\"\n                >\n                  <textarea\n                    lang=\"sw\"\n                    className={`${input} min-h-20`}\n                    value={item.summarySw ?? \"\"}\n                    onChange={(e) =>\n                      set(\"summarySw\", e.target.value || undefined)\n                    }\n                  />\n                </Field>\n              </Section>\n\n              {/* Content by type */}\n              <Section\n                title={\n                  item.kind === \"expert\"\n                    ? \"Question and answer\"\n                    : item.kind === \"video\"\n                      ? \"Video\"\n                      : item.kind === \"reel\"\n                        ? \"Reel (vertical video)\"\n                        : item.kind === \"audio\"\n                          ? \"Audio\"\n                          : item.kind === \"infographic\"\n                            ? \"Infographic\"\n                            : item.kind === \"quiz\"\n                              ? \"Quiz\"\n                              : \"Text\"\n                }\n              >\n                {item.kind === \"expert\" && (\n                  <Field label=\"The question a man asked\">\n                    <textarea\n                      className={`${input} min-h-16`}\n                      value={item.question ?? \"\"}\n                      onChange={(e) =>\n                        set(\"question\", e.target.value || undefined)\n                      }\n                    />\n                  </Field>\n                )}\n                {item.kind === \"infographic\" && (\n                  <p className=\"rounded-2xl bg-mint/60 px-4 py-3 text-xs text-forest-deep\">\n                    The infographic is the <b>cover photo</b> (upload it under\n                    Cover below). It&apos;s shown full size on the page; the\n                    text underneath is optional.\n                  </p>\n                )}\n                {item.kind === \"audio\" && (\n                  <div className=\"space-y-3\">\n                    {item.audioUrl && (\n                      <audio\n                        src={item.audioUrl}\n                        controls\n                        preload=\"metadata\"\n                        className=\"w-full\"\n                      />\n                    )}\n                    <div className=\"flex flex-wrap items-center gap-3\">\n                      <button\n                        type=\"button\"\n                        onClick={() => audioInput.current?.click()}\n                        disabled={busy === \"audio\"}\n                        className=\"flex items-center gap-2 rounded-full bg-forest px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-60\"\n                      >\n                        {busy === \"audio\" ? (\n                          <Loader2 size={16} className=\"animate-spin\" />\n                        ) : (\n                          <Mic size={16} />\n                        )}\n                        {busy === \"audio\"\n                          ? shrink\n                            ? \"Making it smaller…\"\n                            : \"Uploading…\"\n                          : item.audioUrl\n                            ? \"Change audio\"\n                            : \"Upload audio\"}\n                      </button>\n                      {item.audioUrl && (\n                        <button\n                          type=\"button\"\n                          onClick={() => set(\"audioUrl\", undefined)}\n                          className=\"flex items-center gap-1 text-sm font-semibold text-ink-soft\"\n                        >\n                          <X size={14} /> Remove audio\n                        </button>\n                      )}\n                      <input\n                        ref={audioInput}\n                        type=\"file\"\n                        accept=\"audio/*\"\n                        className=\"hidden\"\n                        onChange={(e) => uploadAudio(e.target.files?.[0])}\n                      />\n                      <span className=\"text-xs text-ink-soft\">\n                        MP3, M4A, AAC, OGG or WAV, under 40 MB.\n                      </span>\n                    </div>\n                    <Field\n                      label=\"Or paste an audio link\"\n                      hint=\"A direct https link to an .mp3 or .m4a file.\"\n                    >\n                      <input\n                        className={input}\n                        type=\"url\"\n                        placeholder=\"https://…/episode.mp3\"\n                        value={item.audioUrl ?? \"\"}\n                        onChange={(e) =>\n                          set(\"audioUrl\", e.target.value.trim() || undefined)\n                        }\n                      />\n                    </Field>\n                    <Field\n                      label=\"Key points\"\n                      hint=\"One per line. Shown under the player.\"\n                    >\n                      <textarea\n                        className={`${input} min-h-28`}\n                        value={texts.keyPoints}\n                        onChange={(e) => setText(\"keyPoints\", e.target.value)}\n                      />\n                    </Field>\n                  </div>\n                )}\n                {item.kind === \"reel\" && (\n                  <p className=\"rounded-2xl bg-mint/60 px-4 py-3 text-xs text-forest-deep\">\n                    A reel is a <b>vertical video</b> (filmed upright on a\n                    phone, 9:16), best under 90 seconds. It shows in the Reels\n                    row on Discover and in the feed, and plays full screen. The\n                    title and summary are its caption. A cover photo is optional\n                    (the first frame is used).\n                  </p>\n                )}\n                {(item.kind === \"video\" || item.kind === \"reel\") && (\n                  <div className=\"space-y-3\">\n                    {item.videoUrl && yt && (\n                      <YouTubeFrame\n                        id={yt}\n                        controls\n                        title={item.title || \"Video\"}\n                        onBlocked={() => setYtBlocked(item.videoUrl ?? null)}\n                        className={\n                          item.kind === \"reel\" || isYouTubeShort(item.videoUrl)\n                            ? \"mx-auto aspect-[9/16] max-h-[28rem] w-full max-w-[16rem] rounded-2xl\"\n                            : \"aspect-video w-full rounded-2xl\"\n                        }\n                      />\n                    )}\n                    {item.videoUrl && !yt && (\n                      <ShapedVideo\n                        src={item.videoUrl}\n                        fallback={item.kind === \"reel\" ? UPRIGHT : WIDE}\n                        maxHeight=\"28rem\"\n                        controls\n                        playsInline\n                        preload=\"metadata\"\n                        className=\"rounded-2xl\"\n                      />\n                    )}\n                    <div className=\"flex flex-wrap items-center gap-3\">\n                      <button\n                        type=\"button\"\n                        onClick={() => videoInput.current?.click()}\n                        disabled={busy === \"video\"}\n                        className=\"flex items-center gap-2 rounded-full bg-forest px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-60\"\n                      >\n                        {busy === \"video\" ? (\n                          <Loader2 size={16} className=\"animate-spin\" />\n                        ) : (\n                          <Film size={16} />\n                        )}\n                        {busy === \"video\"\n                          ? shrink\n                            ? \"Making it smaller…\"\n                            : \"Uploading…\"\n                          : item.videoUrl\n                            ? \"Change video\"\n                            : \"Upload video\"}\n                      </button>\n                      {item.videoUrl && (\n                        <button\n                          type=\"button\"\n                          onClick={() => set(\"videoUrl\", undefined)}\n                          className=\"flex items-center gap-1 text-sm font-semibold text-ink-soft\"\n                        >\n                          <X size={14} /> Remove video\n                        </button>\n                      )}\n                      <input\n                        ref={videoInput}\n                        type=\"file\"\n                        accept=\"video/mp4,video/webm,video/quicktime\"\n                        className=\"hidden\"\n                        onChange={(e) => uploadVideo(e.target.files?.[0])}\n                      />\n                      <span className=\"text-xs text-ink-soft\">\n                        {item.kind === \"reel\"\n                          ? \"MP4 or MOV, upright. Over 50 MB is made smaller for you (Chrome). Best under 90 seconds.\"\n                          : \"MP4, WebM or MOV. Over 50 MB is made smaller for you (Chrome). Short is best: 2 minutes or less.\"}\n                      </span>\n                    </div>\n                    <Field\n                      label=\"Or paste a video link\"\n                      hint=\"A YouTube link (plays inside the app) or a direct https link to an .mp4 file. Instagram links go in the post's origin, not here.\"\n                    >\n                      <input\n                        className={input}\n                        type=\"url\"\n                        placeholder=\"https://youtube.com/watch?v=… or https://…/video.mp4\"\n                        value={item.videoUrl ?? \"\"}\n                        onChange={(e) => pasteVideo(e.target.value)}\n                      />\n                    </Field>\n                    {shrinkNote}\n                    {ytNote}\n                  </div>\n                )}\n                {item.kind === \"video\" && (\n                  <Field\n                    label=\"Key points\"\n                    hint=\"One per line. Shown under the video.\"\n                  >\n                    <textarea\n                      className={`${input} min-h-28`}\n                      value={texts.keyPoints}\n                      onChange={(e) => setText(\"keyPoints\", e.target.value)}\n                    />\n                  </Field>\n                )}\n                {item.kind === \"quiz\" && (\n                  <QuizEditor\n                    value={item.quiz ?? []}\n                    onChange={(q) => set(\"quiz\", q)}\n                  />\n                )}\n                {item.kind === \"tool\" && (\n                  <Field group label=\"Which tool\">\n                    <div className=\"flex flex-wrap gap-2\">\n                      {TOOLS.map((t) => (\n                        <Chip\n                          key={t.id}\n                          on={item.tool === t.id}\n                          onClick={() => set(\"tool\", t.id)}\n                        >\n                          {t.label}\n                        </Chip>\n                      ))}\n                    </div>\n                  </Field>\n                )}\n                <Field\n                  label={\n                    item.kind === \"expert\"\n                      ? \"Answer (English)\"\n                      : \"Text (English)\"\n                  }\n                  hint='Leave an empty line between paragraphs. Start a line with \"## \" to make a heading.'\n                >\n                  <textarea\n                    className={`${input} min-h-56 leading-relaxed`}\n                    value={texts.body}\n                    onChange={(e) => setText(\"body\", e.target.value)}\n                  />\n                </Field>\n                <Field\n                  label=\"Text (Kiswahili)\"\n                  hint=\"Optional. Readers can switch language on the page.\"\n                >\n                  <textarea\n                    lang=\"sw\"\n                    className={`${input} min-h-40 leading-relaxed`}\n                    value={texts.bodySw}\n                    onChange={(e) => setText(\"bodySw\", e.target.value)}\n                  />\n                </Field>\n              </Section>\n\n              {/* Where men see it */}\n              {/* Step 86: hooks on a \"do this\" card (question first, series, challenge, share title) */}\n              {actionOf(item) && (\n                <Section title=\"Hooks on Discover\">\n                  <HookFields\n                    spec={actionOf(item)!}\n                    cardId={item.id}\n                    onChange={(patch) => setDraft((d) => ({ ...d, action: { ...actionOf(d)!, ...patch } }))}\n                  />\n                </Section>\n              )}\n\n              <Section title=\"Where it shows\">\n                <ul className=\"flex flex-wrap gap-2\">\n                  {placesOf(item).map((p) => (\n                    <li\n                      key={p.id}\n                      className=\"flex items-center gap-1 rounded-full bg-mint/70 px-3 py-1.5 text-xs font-semibold text-forest-deep\"\n                    >\n                      <MapPin size={12} />\n                      {p.id === \"library\"\n                        ? `Library · ${TOPICS.find((t) => t.id === item.topic)?.title ?? \"no topic\"}`\n                        : p.title}\n                    </li>\n                  ))}\n                </ul>\n                <p className=\"text-xs text-ink-soft\">\n                  {item.kind === \"reel\"\n                    ? \"Reels show in the Reels row and between the cards on Discover. To put this one first for everyone, pin it in \"\n                    : \"Discover now shows reels and “do this” cards. Guides, articles and videos reach men through search, Saved, Kito, topic pages and links. To pin or hide things on Discover, use \"}\n                  <Link\n                    href=\"/studio/discover\"\n                    className=\"font-semibold text-forest underline\"\n                  >\n                    Studio → Discover\n                  </Link>\n                  .\n                </p>\n                <label className=\"flex items-start gap-3 text-sm\">\n                  <input\n                    type=\"checkbox\"\n                    className=\"mt-1 accent-forest\"\n                    checked={Boolean(item.inManFeed)}\n                    onChange={(e) => set(\"inManFeed\", e.target.checked)}\n                  />\n                  <span>\n                    <b>Show as a daily lesson on the Man tab</b>\n                    <span className=\"block text-xs text-ink-soft\">\n                      He earns the points below when he marks it as read.\n                    </span>\n                  </span>\n                </label>\n              </Section>\n\n              {/* Publishing: schedule, review, AI */}\n              <Section title=\"Publishing\">\n                <Field\n                  label=\"Go live at (optional)\"\n                  hint={\n                    item.publishAt && new Date(item.publishAt) > new Date()\n                      ? \"Scheduled: men see it from this time. Leave empty to go live as soon as it's published.\"\n                      : \"Leave empty to go live as soon as it's published. Pick a future time to schedule it.\"\n                  }\n                >\n                  <div className=\"flex flex-wrap items-center gap-2\">\n                    <input\n                      type=\"datetime-local\"\n                      className={`${input} max-w-xs`}\n                      value={item.publishAt ? toLocalInput(item.publishAt) : \"\"}\n                      onChange={(e) =>\n                        set(\n                          \"publishAt\",\n                          e.target.value\n                            ? new Date(e.target.value).toISOString()\n                            : undefined,\n                        )\n                      }\n                    />\n                    {item.publishAt && (\n                      <button\n                        type=\"button\"\n                        onClick={() => set(\"publishAt\", undefined)}\n                        className=\"text-xs font-semibold text-ink-soft\"\n                      >\n                        Clear\n                      </button>\n                    )}\n                  </div>\n                </Field>\n                <Field\n                  label=\"Note for review (optional)\"\n                  hint=\"What the writer or editor should know. Shown at the top while it's in review.\"\n                >\n                  <textarea\n                    className={`${input} min-h-16`}\n                    maxLength={500}\n                    value={item.reviewNote ?? \"\"}\n                    onChange={(e) =>\n                      set(\"reviewNote\", e.target.value || undefined)\n                    }\n                  />\n                </Field>\n                <label className=\"flex items-start gap-3 text-sm\">\n                  <input\n                    type=\"checkbox\"\n                    className=\"mt-1 accent-forest\"\n                    checked={Boolean(item.aiGenerated)}\n                    onChange={(e) =>\n                      set(\"aiGenerated\", e.target.checked || undefined)\n                    }\n                  />\n                  <span>\n                    <b>Drafted with AI help</b>\n                    <span className=\"block text-xs text-ink-soft\">\n                      For your records only. Staff can publish it straight away.\n                    </span>\n                  </span>\n                </label>\n              </Section>\n\n              {/* Look */}\n              <Section title=\"Cover\">\n                <div className=\"flex flex-wrap items-center gap-3\">\n                  <button\n                    type=\"button\"\n                    onClick={() => fileInput.current?.click()}\n                    disabled={busy === \"image\"}\n                    className=\"flex items-center gap-2 rounded-full bg-forest px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-60\"\n                  >\n                    {busy === \"image\" ? (\n                      <Loader2 size={16} className=\"animate-spin\" />\n                    ) : (\n                      <ImagePlus size={16} />\n                    )}\n                    {item.coverImageUrl ? \"Change photo\" : \"Upload photo\"}\n                  </button>\n                  {item.coverImageUrl && (\n                    <button\n                      type=\"button\"\n                      onClick={() => set(\"coverImageUrl\", undefined)}\n                      className=\"flex items-center gap-1 text-sm font-semibold text-ink-soft\"\n                    >\n                      <X size={14} /> Remove photo\n                    </button>\n                  )}\n                  <input\n                    ref={fileInput}\n                    type=\"file\"\n                    accept=\"image/jpeg,image/png,image/webp\"\n                    className=\"hidden\"\n                    onChange={(e) => upload(e.target.files?.[0])}\n                  />\n                  <span className=\"text-xs text-ink-soft\">\n                    JPG, PNG or WebP, under 3 MB. No intimate photos.\n                  </span>\n                </div>\n                {!item.coverImageUrl && (\n                  <Field group label=\"Or a drawn cover\">\n                    <div className=\"flex flex-wrap items-center gap-2\">\n                      {TONES.map((t) => (\n                        <button\n                          key={t}\n                          type=\"button\"\n                          aria-label={t}\n                          aria-pressed={item.cover.tone === t}\n                          onClick={() =>\n                            set(\"cover\", { ...item.cover, tone: t })\n                          }\n                          className={`h-8 w-8 rounded-full ring-1 ring-line ${item.cover.tone === t ? \"outline-2 outline-offset-2 outline-forest\" : \"\"}`}\n                          style={{ background: TONE_SWATCH[t] }}\n                        />\n                      ))}\n                      <span className=\"mx-1 h-6 w-px bg-line\" />\n                      {MOTIFS.map((m) => (\n                        <Chip\n                          key={m}\n                          on={item.cover.motif === m}\n                          onClick={() =>\n                            set(\"cover\", { ...item.cover, motif: m })\n                          }\n                        >\n                          {m[0].toUpperCase() + m.slice(1)}\n                        </Chip>\n                      ))}\n                    </div>\n                  </Field>\n                )}\n              </Section>\n\n              {/* Details */}\n              <Section title=\"Details\">\n                <div className=\"grid gap-4 sm:grid-cols-3\">\n                  <Field label=\"Minutes to read\">\n                    <input\n                      type=\"number\"\n                      min={1}\n                      max={60}\n                      className={input}\n                      value={item.minutes}\n                      onChange={(e) =>\n                        set(\"minutes\", clamp(e.target.value, 1, 60, 3))\n                      }\n                    />\n                  </Field>\n                  <Field\n                    label=\"Priority (0–100)\"\n                    hint=\"Higher comes first in search, topic pages and the Man tab.\"\n                  >\n                    <input\n                      type=\"number\"\n                      min={0}\n                      max={100}\n                      className={input}\n                      value={item.priority}\n                      onChange={(e) =>\n                        set(\"priority\", clamp(e.target.value, 0, 100, 50))\n                      }\n                    />\n                  </Field>\n                  <Field label=\"Points\">\n                    <input\n                      type=\"number\"\n                      min={0}\n                      max={100}\n                      className={input}\n                      value={item.points ?? 10}\n                      onChange={(e) =>\n                        set(\"points\", clamp(e.target.value, 0, 100, 10))\n                      }\n                    />\n                  </Field>\n                </div>\n                <Field\n                  label=\"Tags\"\n                  hint=\"Separate with commas. Helps search, e.g. sleep, energy, usingizi\"\n                >\n                  <input\n                    className={input}\n                    value={texts.tags}\n                    onChange={(e) => setText(\"tags\", e.target.value)}\n                  />\n                </Field>\n                <Field\n                  label=\"Source\"\n                  hint=\"Shown to readers: who wrote it and where facts come from.\"\n                >\n                  <input\n                    className={input}\n                    value={item.source}\n                    onChange={(e) => set(\"source\", e.target.value)}\n                  />\n                </Field>\n              </Section>\n            </>\n          )}\n        </div>\n\n        {/* Right side: checks and preview */}\n        <aside className=\"space-y-5\">\n          <div\n            className={`space-y-3 rounded-3xl bg-surface p-5 ring-1 ring-line ${quick ? \"hidden\" : \"\"}`}\n          >\n            <p className=\"font-bold\">Claim check</p>\n            {claims.length === 0 ? (\n              <p className=\"flex items-center gap-2 text-sm text-forest\">\n                <CheckCircle2 size={16} /> No selling, promises or contact\n                details found.\n              </p>\n            ) : (\n              <ul className=\"space-y-2\">\n                {[...blocks, ...warns].map((c, i) => (\n                  <li\n                    key={i}\n                    className={`flex gap-2 rounded-2xl px-3 py-2 text-xs ${c.level === \"block\" ? \"bg-red-50 text-red-800\" : \"bg-amber-50 text-amber-900\"}`}\n                  >\n                    {c.level === \"block\" ? (\n                      <OctagonX size={14} className=\"mt-px shrink-0\" />\n                    ) : (\n                      <AlertTriangle size={14} className=\"mt-px shrink-0\" />\n                    )}\n                    <span>\n                      <b>&ldquo;{c.match}&rdquo;</b> · {c.message}\n                    </span>\n                  </li>\n                ))}\n              </ul>\n            )}\n            <p className=\"pt-1 font-bold\">Ready to publish?</p>\n            {problems.length === 0 ? (\n              <p className=\"flex items-center gap-2 text-sm text-forest\">\n                <CheckCircle2 size={16} /> Yes, everything needed is there.\n              </p>\n            ) : (\n              <ul className=\"list-disc space-y-1 pl-5 text-xs text-ink-soft\">\n                {problems.map((p) => (\n                  <li key={p}>{p}</li>\n                ))}\n              </ul>\n            )}\n          </div>\n          <Preview item={item} />\n        </aside>\n      </div>\n\n      {/* Actions: stick to the bottom of the editor while scrolling */}\n      <div className=\"sticky bottom-0 z-20 -mx-4 border-t border-line bg-surface/95 px-4 py-3 backdrop-blur sm:-mx-6 sm:px-6 lg:-mx-8 lg:px-8\">\n        <div className=\"flex flex-wrap items-center gap-2\">\n          {error ? (\n            <p role=\"alert\" className=\"mr-auto max-w-md text-sm text-red-700\">\n              {error}\n            </p>\n          ) : (\n            <p className=\"mr-auto hidden text-xs text-ink-soft sm:block\">\n              {status === \"published\"\n                ? item.publishAt && new Date(item.publishAt) > new Date()\n                  ? \"Scheduled. Men see it from the time you set.\"\n                  : \"Men can see this now.\"\n                : status === \"review\"\n                  ? canPublish\n                    ? \"Waiting for your review.\"\n                    : \"Waiting for an editor to review.\"\n                  : canPublish\n                    ? \"Only staff can see drafts.\"\n                    : \"Writers submit for review; an editor publishes.\"}\n            </p>\n          )}\n          {status &&\n            status !== \"published\" &&\n            (canPublish || status !== \"archived\") && (\n              <button\n                onClick={() => setConfirmDelete(true)}\n                disabled={!!busy}\n                className={ghost}\n              >\n                <Trash2 size={14} /> Delete\n              </button>\n            )}\n          {status === \"published\" && canPublish && (\n            <>\n              <button\n                onClick={() => save(\"archived\")}\n                disabled={!!busy}\n                className={ghost}\n              >\n                <Archive size={14} /> Archive\n              </button>\n              <button\n                onClick={() => save(\"draft\")}\n                disabled={!!busy}\n                className={ghost}\n              >\n                Unpublish\n              </button>\n            </>\n          )}\n          {status !== \"published\" && (\n            <button\n              onClick={() => save(\"draft\")}\n              disabled={!!busy || (!dirty && status === \"draft\")}\n              className={ghost}\n            >\n              {busy === \"draft\" && (\n                <Loader2 size={14} className=\"animate-spin\" />\n              )}\n              {status === \"archived\"\n                ? \"Restore as draft\"\n                : status === \"review\"\n                  ? \"Back to draft\"\n                  : \"Save draft\"}\n            </button>\n          )}\n          {!canPublish &&\n            status !== \"published\" &&\n            status !== \"archived\" &&\n            (status !== \"review\" || dirty) && (\n              <button\n                onClick={() => save(\"review\")}\n                disabled={!!busy || problems.length > 0}\n                className={canPublish ? ghost : primaryBtn}\n              >\n                {busy === \"review\" && (\n                  <Loader2 size={14} className=\"animate-spin\" />\n                )}\n                {status === \"review\"\n                  ? \"Save review changes\"\n                  : \"Submit for review\"}\n              </button>\n            )}\n          {canPublish ? (\n            <button\n              onClick={() => save(\"published\")}\n              disabled={\n                !!busy ||\n                problems.length > 0 ||\n                (status === \"published\" && !dirty)\n              }\n              className={primaryBtn}\n            >\n              {busy === \"published\" && (\n                <Loader2 size={14} className=\"animate-spin\" />\n              )}\n              {item.publishAt && new Date(item.publishAt) > new Date()\n                ? status === \"published\"\n                  ? \"Update schedule\"\n                  : \"Schedule\"\n                : status === \"published\"\n                  ? \"Update live version\"\n                  : \"Publish\"}\n            </button>\n          ) : (\n            status === \"published\" && (\n              <p className=\"text-xs text-ink-soft\">\n                Live content can only be changed by an editor or owner.\n              </p>\n            )\n          )}\n        </div>\n      </div>\n\n      <Confirm\n        open={confirmDelete}\n        title={`Delete \"${item.title}\"?`}\n        confirmLabel=\"Delete for good\"\n        danger\n        typeToConfirm=\"delete\"\n        onConfirm={remove}\n        onClose={() => setConfirmDelete(false)}\n      >\n        It&apos;s removed from the Studio\n        {status === \"published\" ? \" and from the app\" : \"\"}. This can&apos;t be\n        undone. Earlier versions are deleted too. To keep it out of the app but\n        keep a copy, use Archive instead.\n      </Confirm>\n\n      <Drawer\n        open={showHistory}\n        title=\"Version history\"\n        onClose={() => setShowHistory(false)}\n      >\n        {versions === null ? (\n          <p className=\"flex items-center gap-2 text-sm text-ink-soft\">\n            <Loader2 size={16} className=\"animate-spin\" /> Loading…\n          </p>\n        ) : versions.length === 0 ? (\n          <p className=\"text-sm text-ink-soft\">\n            No earlier versions yet. Each time you save a change, the previous\n            version is kept here (the last 30).\n          </p>\n        ) : (\n          <ul className=\"space-y-2\">\n            {versions.map((v) => (\n              <li key={v.id} className=\"rounded-xl p-3 ring-1 ring-line\">\n                <div className=\"flex items-start justify-between gap-2\">\n                  <div className=\"min-w-0\">\n                    <p className=\"truncate text-sm font-semibold\">\n                      {v.item.title}\n                    </p>\n                    <p className=\"text-[0.6875rem] text-ink-soft\">\n                      <Clock size={11} className=\"mr-1 inline\" />\n                      {new Date(v.savedAt).toLocaleString(\"en-GB\", {\n                        day: \"numeric\",\n                        month: \"short\",\n                        hour: \"2-digit\",\n                        minute: \"2-digit\",\n                      })}{\" \"}\n                      · was {v.status}\n                    </p>\n                    <p className=\"mt-1 line-clamp-2 text-xs text-ink-soft\">\n                      {v.item.summary}\n                    </p>\n                  </div>\n                  <button onClick={() => loadVersion(v)} className={btn.small}>\n                    Load\n                  </button>\n                </div>\n              </li>\n            ))}\n          </ul>\n        )}\n      </Drawer>\n    </div>\n  );\n}\n\nfunction QuizEditor({\n  value,\n  onChange,\n}: {\n  value: QuizQuestion[];\n  onChange: (q: QuizQuestion[]) => void;\n}) {\n  const update = (i: number, patch: Partial<QuizQuestion>) =>\n    onChange(value.map((q, j) => (j === i ? { ...q, ...patch } : q)));\n  return (\n    <div className=\"space-y-4\">\n      {value.map((q, i) => (\n        <div\n          key={i}\n          className=\"space-y-3 rounded-2xl bg-bg p-4 ring-1 ring-line\"\n        >\n          <div className=\"flex items-center justify-between\">\n            <p className=\"text-xs font-bold text-ink-soft\">Question {i + 1}</p>\n            <button\n              type=\"button\"\n              onClick={() => onChange(value.filter((_, j) => j !== i))}\n              className=\"text-xs font-semibold text-ink-soft\"\n            >\n              Remove\n            </button>\n          </div>\n          <input\n            className={input}\n            placeholder=\"Question\"\n            value={q.q}\n            onChange={(e) => update(i, { q: e.target.value })}\n          />\n          {q.options.map((o, oi) => (\n            <label key={oi} className=\"flex items-center gap-2\">\n              <input\n                type=\"radio\"\n                name={`answer-${i}`}\n                className=\"accent-forest\"\n                checked={q.answer === oi}\n                onChange={() => update(i, { answer: oi })}\n                aria-label=\"Correct answer\"\n              />\n              <input\n                className={input}\n                placeholder={`Answer ${oi + 1}`}\n                value={o}\n                onChange={(e) =>\n                  update(i, {\n                    options: q.options.map((x, xi) =>\n                      xi === oi ? e.target.value : x,\n                    ),\n                  })\n                }\n              />\n            </label>\n          ))}\n          <p className=\"text-[0.6875rem] text-ink-soft\">\n            Tick the circle next to the correct answer.\n          </p>\n          <input\n            className={input}\n            placeholder=\"Why this is the answer (shown after he answers)\"\n            value={q.explain}\n            onChange={(e) => update(i, { explain: e.target.value })}\n          />\n        </div>\n      ))}\n      <button\n        type=\"button\"\n        onClick={() =>\n          onChange([\n            ...value,\n            { q: \"\", options: [\"\", \"\", \"\"], answer: 0, explain: \"\" },\n          ])\n        }\n        className=\"flex items-center gap-1.5 rounded-full px-4 py-2 text-sm font-semibold text-forest ring-1 ring-line\"\n      >\n        <Plus size={14} /> Add question\n      </button>\n    </div>\n  );\n}\n\nfunction Section({\n  title,\n  children,\n}: {\n  title: string;\n  children: React.ReactNode;\n}) {\n  return (\n    <section className=\"space-y-4 rounded-3xl bg-surface p-5 ring-1 ring-line\">\n      <h2 className=\"font-bold\">{title}</h2>\n      {children}\n    </section>\n  );\n}\n\n/** A labelled field. `group` is for rows of buttons (a <label> would make clicks on the text press the first button). */\nfunction Field({\n  label,\n  hint,\n  group,\n  children,\n}: {\n  label: string;\n  hint?: string;\n  group?: boolean;\n  children: React.ReactNode;\n}) {\n  const Tag = group ? \"div\" : \"label\";\n  return (\n    <Tag className=\"block\">\n      <span className=\"text-xs font-semibold text-ink-soft\">{label}</span>\n      <div className=\"mt-1\">{children}</div>\n      {hint && (\n        <span className=\"mt-1 block text-[0.6875rem] text-ink-soft\">\n          {hint}\n        </span>\n      )}\n    </Tag>\n  );\n}\n\n/** The Discover circles, as staff pick them for a piece of content (Step 80). */\nfunction CirclePicker({ item, onChange }: { item: ContentItem; onChange: (circles: ChallengeId[], noCircleTopic?: TopicId) => void }) {\n  const on = circlesOf({ ...item, action: actionOf(item) });\n  const btn = (active: boolean) =>\n    `rounded-full px-3 py-1.5 text-xs font-semibold ring-1 ${active ? \"bg-forest text-white ring-forest\" : \"ring-line\"}`;\n  return (\n    <div className=\"space-y-2\">\n      <div className=\"flex flex-wrap gap-1.5\">\n        {CIRCLES.map((c) => {\n          const active = on.includes(c.id);\n          return (\n            <button\n              key={c.id}\n              type=\"button\"\n              aria-pressed={active}\n              onClick={() => onChange(active ? on.filter((x) => x !== c.id) : [...on, c.id])}\n              className={btn(active)}\n            >\n              {c.label}\n            </button>\n          );\n        })}\n      </div>\n      <div className=\"flex flex-wrap items-center gap-1.5\">\n        <span className=\"text-[0.6875rem] text-ink-soft\">Fits no circle (shows in For you):</span>\n        {NO_CIRCLE.map((n) => {\n          const active = on.length === 0 && item.topic === n.topic;\n          return (\n            <button key={n.topic} type=\"button\" aria-pressed={active} onClick={() => onChange([], n.topic)} className={btn(active)}>\n              {n.label}\n            </button>\n          );\n        })}\n      </div>\n    </div>\n  );\n}\n\nfunction Chip({\n  on,\n  onClick,\n  children,\n}: {\n  on: boolean;\n  onClick: () => void;\n  children: React.ReactNode;\n}) {\n  return (\n    <button\n      type=\"button\"\n      onClick={onClick}\n      aria-pressed={on}\n      className={`rounded-full px-3.5 py-1.5 text-xs font-semibold ${on ? \"bg-forest-deep text-white\" : \"bg-bg text-ink-soft ring-1 ring-line\"}`}\n    >\n      {children}\n    </button>\n  );\n}\n\n/** ISO time → value for <input type=\"datetime-local\"> in local time */\nconst toLocalInput = (iso: string) => {\n  const d = new Date(iso);\n  const pad = (n: number) => String(n).padStart(2, \"0\");\n  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;\n};\n\nconst clamp = (v: string, min: number, max: number, fallback: number) => {\n  const n = Math.round(Number(v));\n  return Number.isFinite(n) ? Math.min(max, Math.max(min, n)) : fallback;\n};\n\nconst input =\n  \"w-full rounded-2xl bg-bg px-4 py-2.5 text-sm outline-none ring-1 ring-line focus:ring-2 focus:ring-forest disabled:opacity-60\";\nconst primaryBtn =\n  \"flex items-center gap-1.5 rounded-full bg-forest px-5 py-2.5 text-sm font-semibold text-white transition-transform active:scale-[0.98] disabled:opacity-40\";\nconst ghost =\n  \"flex items-center gap-1.5 rounded-full px-4 py-2.5 text-sm font-semibold text-ink ring-1 ring-line disabled:opacity-40\";\n","src/components/studio/Preview.tsx":"\"use client\";\n\nimport { UPRIGHT, useVideoShape } from \"@/lib/media/videoShape\";\nimport { captionPreview, cleanTitle } from \"@/lib/content/caption\";\nimport { useState } from \"react\";\nimport { MessageCircle, PlayCircle, ShieldCheck } from \"lucide-react\";\nimport Cover from \"@/components/social/Cover\";\nimport { TOPICS } from \"@/lib/content/library\";\nimport { CTA_LABEL, KIND_LABEL } from \"@/lib/content/select\";\nimport type { ContentItem } from \"@/lib/content/types\";\nimport { reelCaption } from \"@/lib/content/reels\";\nimport { youtubeId } from \"@/lib/content/youtube\";\nimport { YouTubeFrame } from \"@/components/media/YouTubeFrame\";\n\n/** How the item will look on a man's phone: the Discover card, then the opened page. */\nexport default function Preview({ item }: { item: ContentItem }) {\n  const [lang, setLang] = useState<\"en\" | \"sw\">(\"en\");\n  const sw = lang === \"sw\";\n  const title = (sw && item.titleSw) || item.title || \"Your title\";\n  const body = sw ? item.bodySw : item.body;\n  const topic = TOPICS.find((t) => t.id === item.topic)?.title;\n\n  return (\n    <div className=\"space-y-3\">\n      <div className=\"flex items-center justify-between\">\n        <p className=\"text-xs font-semibold uppercase tracking-wider text-ink-soft\">\n          Phone preview\n        </p>\n        <div className=\"inline-flex rounded-full bg-surface p-0.5 text-[0.6875rem] font-semibold ring-1 ring-line\">\n          {([\"en\", \"sw\"] as const).map((l) => (\n            <button\n              key={l}\n              onClick={() => setLang(l)}\n              className={`rounded-full px-2.5 py-1 ${lang === l ? \"bg-forest text-white\" : \"text-ink-soft\"}`}\n            >\n              {l === \"en\" ? \"EN\" : \"SW\"}\n            </button>\n          ))}\n        </div>\n      </div>\n\n      <div className=\"mx-auto w-full max-w-[340px] overflow-hidden rounded-[36px] border-[6px] border-ink bg-bg shadow-xl\">\n        <div className=\"max-h-[640px] space-y-4 overflow-y-auto p-4 [scrollbar-width:thin]\">\n          {item.kind === \"reel\" ? (\n            /* A reel as it plays full screen on Discover */\n            <div className=\"relative -m-4 aspect-[9/16] overflow-hidden bg-forest-deep\">\n              {youtubeId(item.videoUrl) ? (\n                <YouTubeFrame id={youtubeId(item.videoUrl)!} playing muted loop title={title} className=\"absolute inset-0\" />\n              ) : item.videoUrl ? (\n<ReelVideo src={item.videoUrl} poster={item.coverImageUrl} />\n              ) : (\n                <div className=\"absolute inset-0 flex items-center justify-center text-xs text-white/70\">\n                  Upload the video to see it here\n                </div>\n              )}\n              <span className=\"absolute inset-0 bg-gradient-to-t from-black/80 via-transparent to-black/20\" />\n              <div className=\"absolute inset-x-4 bottom-5 pr-12 text-white\">\n                <p className=\"text-[0.625rem] font-semibold uppercase tracking-wider text-mint\">\n                  Reel\n                </p>\n                <p className=\"mt-1 font-bold leading-snug\">{cleanTitle(title)}</p>\n                <p className=\"mt-1 line-clamp-3 text-xs text-white/85\">\n                  {captionPreview(reelCaption(item, sw))}\n                </p>\n              </div>\n            </div>\n          ) : (\n            /* How it shows in search, Saved, topic pages and Kito's links */\n            <div className=\"flex gap-3 rounded-2xl bg-surface p-3 ring-1 ring-line\">\n              <Cover\n                item={item}\n                className=\"h-16 w-16 shrink-0 rounded-xl\"\n                showPlay={false}\n              />\n              <div className=\"min-w-0\">\n                <p className=\"text-[0.625rem] font-semibold uppercase tracking-wider text-forest\">\n                  {KIND_LABEL[item.kind]} · {item.minutes} min\n                </p>\n                <p className=\"mt-0.5 line-clamp-2 text-sm font-bold leading-snug\">\n                  {title}\n                </p>\n                <p className=\"mt-0.5 text-[0.625rem] text-ink-soft\">\n                  In search, Saved, topic pages and Kito ·{\" \"}\n                  {CTA_LABEL[item.kind]} →\n                </p>\n              </div>\n            </div>\n          )}\n\n          {item.kind !== \"reel\" && (\n            <>\n              <p className=\"text-center text-[0.625rem] uppercase tracking-wider text-ink-soft\">\n                Opened page\n              </p>\n\n              {item.kind === \"video\" && (\n                <div className=\"relative overflow-hidden rounded-3xl\">\n                  <Cover\n                    item={item}\n                    className=\"aspect-video w-full\"\n                    showPlay={false}\n                  />\n                  <div className=\"absolute inset-0 flex items-center justify-center bg-black/30 text-white\">\n                    <PlayCircle size={36} />\n                  </div>\n                </div>\n              )}\n              <div>\n                <p className=\"text-[0.625rem] font-semibold uppercase tracking-wider text-forest\">\n                  {topic} · {KIND_LABEL[item.kind]}\n                </p>\n                <h2 className=\"mt-1 text-xl font-bold leading-tight\">\n                  {title}\n                </h2>\n                {!sw && item.summary && (\n                  <p className=\"mt-1 text-sm text-ink-soft\">{item.summary}</p>\n                )}\n                <p className=\"mt-2 flex items-start gap-1 rounded-xl bg-surface px-2 py-1.5 text-[0.625rem] text-ink-soft ring-1 ring-line\">\n                  <ShieldCheck\n                    size={11}\n                    className=\"mt-px shrink-0 text-forest\"\n                  />\n                  {item.source}\n                  {item.review === \"reviewed\" ? \" · Reviewed\" : \"\"}\n                </p>\n              </div>\n\n              {item.kind === \"expert\" && item.question && (\n                <blockquote className=\"flex gap-2 rounded-2xl bg-mint/60 p-3 text-xs italic text-forest-deep\">\n                  <MessageCircle\n                    size={14}\n                    className=\"mt-0.5 shrink-0 text-forest\"\n                  />\n                  “{item.question}”\n                </blockquote>\n              )}\n\n              {sw && !item.bodySw?.length ? (\n                <p className=\"rounded-2xl bg-amber-50 p-3 text-xs text-amber-800\">\n                  No Kiswahili text yet. Readers will only see English.\n                </p>\n              ) : (\n                body &&\n                body.length > 0 && (\n                  <div className=\"space-y-2 rounded-2xl bg-surface p-4 text-sm leading-relaxed ring-1 ring-line\">\n                    {body.map((p, i) =>\n                      p.startsWith(\"## \") ? (\n                        <h3 key={i} className=\"pt-1 font-bold\">\n                          {p.slice(3)}\n                        </h3>\n                      ) : (\n                        <p key={i}>{p}</p>\n                      ),\n                    )}\n                  </div>\n                )\n              )}\n\n              {item.keyPoints && item.keyPoints.length > 0 && (\n                <ol className=\"space-y-1.5 rounded-2xl bg-surface p-4 text-xs ring-1 ring-line\">\n                  {item.keyPoints.map((k, i) => (\n                    <li key={i} className=\"flex gap-2\">\n                      <span className=\"font-bold text-forest\">{i + 1}.</span>\n                      {k}\n                    </li>\n                  ))}\n                </ol>\n              )}\n\n              {item.quiz && item.quiz.length > 0 && (\n                <div className=\"rounded-2xl bg-surface p-4 text-xs ring-1 ring-line\">\n                  <p className=\"font-bold\">\n                    Quiz · {item.quiz.length} questions\n                  </p>\n                  <p className=\"mt-1 text-ink-soft\">\n                    {item.quiz[0].q || \"First question\"}\n                  </p>\n                </div>\n              )}\n            </>\n          )}\n        </div>\n      </div>\n    </div>\n  );\n}\n\n/** Step 92: as the reel plays full screen: phone-shaped fills the screen, wide shows whole. */\nfunction ReelVideo({ src, poster }: { src: string; poster?: string }) {\n  const shape = useVideoShape(src, UPRIGHT);\n  return (\n    <video\n      src={src}\n      poster={poster}\n      muted\n      loop\n      playsInline\n      autoPlay\n      onLoadedMetadata={shape.measure}\n      className={`absolute inset-0 h-full w-full ${shape.ratio < 0.7 ? \"object-cover\" : \"object-contain\"}`}\n    />\n  );\n}\n"};

for (const [path, text] of Object.entries(files)) {
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, text);
  console.log("wrote", path);
}
console.log("\nStep 92 done. Now: npm run dev");
